// Shared fixture, allocator, public-output oracle and measurement boundaries.
// Both wrappers and this include must be frozen and bound in link receipts.
use pine_runtime::*;
use pine_sema::analyze_source;
use pine_syntax::{Severity, SourceFile};
use serde_json::{Value, json};
use std::alloc::{GlobalAlloc, Layout, System};
use std::hint::black_box;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicUsize, Ordering::Relaxed};
use std::time::Instant;

const SAMPLES: usize = 9;
struct CountingAllocator;
static LIVE: AtomicUsize = AtomicUsize::new(0);
static PEAK: AtomicUsize = AtomicUsize::new(0);
static ALLOCATED: AtomicUsize = AtomicUsize::new(0);
static ALLOCS: AtomicUsize = AtomicUsize::new(0);
fn allocation(size: usize) {
    ALLOCATED.fetch_add(size, Relaxed);
    ALLOCS.fetch_add(1, Relaxed);
    let live = LIVE.fetch_add(size, Relaxed) + size;
    PEAK.fetch_max(live, Relaxed);
}
unsafe impl GlobalAlloc for CountingAllocator {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        let pointer = unsafe { System.alloc(layout) };
        if !pointer.is_null() {
            allocation(layout.size());
        }
        pointer
    }
    unsafe fn dealloc(&self, pointer: *mut u8, layout: Layout) {
        LIVE.fetch_sub(layout.size(), Relaxed);
        unsafe { System.dealloc(pointer, layout) }
    }
    unsafe fn realloc(&self, pointer: *mut u8, layout: Layout, size: usize) -> *mut u8 {
        let next = unsafe { System.realloc(pointer, layout, size) };
        if !next.is_null() {
            LIVE.fetch_sub(layout.size(), Relaxed);
            allocation(size);
        }
        next
    }
}
#[global_allocator]
static GLOBAL: CountingAllocator = CountingAllocator;
#[derive(Clone, Copy)]
struct Stage {
    ms: f64,
    bytes: usize,
    count: usize,
    peak: usize,
    live_delta: i64,
}
fn measure<T>(call: impl FnOnce() -> T) -> (T, Stage) {
    let initial = LIVE.load(Relaxed);
    PEAK.store(initial, Relaxed);
    let bytes = ALLOCATED.load(Relaxed);
    let count = ALLOCS.load(Relaxed);
    let start = Instant::now();
    let result = black_box(call());
    let ms = start.elapsed().as_secs_f64() * 1000.0;
    (
        result,
        Stage {
            ms,
            bytes: ALLOCATED.load(Relaxed) - bytes,
            count: ALLOCS.load(Relaxed) - count,
            peak: PEAK.load(Relaxed).saturating_sub(initial),
            live_delta: LIVE.load(Relaxed) as i64 - initial as i64,
        },
    )
}
fn stage_json(stage: Stage) -> Value {
    json!({"ms": stage.ms, "allocatedBytes": stage.bytes, "allocations": stage.count,
        "peakAdditionalLiveBytes": stage.peak, "liveDeltaBytes": stage.live_delta})
}
fn fixture_source(count: usize, prefix_chars: usize) -> String {
    if count == 0 {
        return "//@version=6\nindicator(\"alert copy probe\")\nplot(close)\n".into();
    }
    format!(
        "//@version=6\nindicator(\"alert copy probe\")\nif barstate.isrealtime\n    prefix = str.repeat(\"x\", {prefix_chars})\n    for loopindex = 0 to {}\n        alert(prefix + \"|\" + str.tostring(close) + \"|\" + str.tostring(loopindex), alert.freq_all)\nplot(close)\n",
        count - 1
    )
}
fn bar(index: usize, price: f64) -> Bar {
    Bar {
        time: 1_700_000_000 + index as i64 * 60,
        open: price,
        high: price + 1.0,
        low: price - 1.0,
        close: price,
        volume: 100.0,
    }
}
struct Fixture {
    count: usize,
    prefix: String,
    alert_id: Option<u32>,
    plot_id: u32,
}
impl Fixture {
    fn events(&self, index: usize, price: u32) -> Vec<AlertEvent> {
        (0..self.count)
            .map(|item| AlertEvent {
                id: self.alert_id.expect("alert callsite in HIR"),
                bar_index: index,
                time: 1_700_000_000 + index as i64 * 60,
                message: format!("{}|{price}|{item}", self.prefix),
                source: "alert".into(),
            })
            .collect()
    }
    fn check_view(
        &self,
        view: RuntimeResultView<'_>,
        prices: &[u32],
        alerts: &[AlertEvent],
    ) -> Result<(), String> {
        if view.plots.len() != 1
            || view.plots[0].id != self.plot_id
            || view.plots[0].values.len() != prices.len()
        {
            return Err("one complete fixture plot with HIR id required".into());
        }
        for (actual, expected) in view.plots[0].values.iter().zip(prices) {
            check_value(actual, *expected)?;
        }
        if view.alerts.len() != alerts.len() || !view.alerts.iter().eq(alerts.iter()) {
            return Err("complete ordered alert payload diverged from fixture arithmetic".into());
        }
        if !view.diagnostics.is_empty() || view.strategy.is_some() {
            return Err("unexpected fixture diagnostic or strategy".into());
        }
        // Check the whole public shape/default omission outside measurements,
        // in addition to the direct typed price/event formulas above.
        let encoded = public_runtime_result_view_json(&view);
        let document: Value = serde_json::from_str(&encoded).map_err(|error| error.to_string())?;
        let empty_families = [
            "plotChars",
            "plotShapes",
            "plotArrows",
            "plotBars",
            "plotCandles",
            "bgColors",
            "barColors",
            "hlines",
            "fills",
            "labels",
            "lines",
            "lineFills",
            "polylines",
            "boxes",
            "tables",
            "diagnostics",
        ];
        if document.as_object().map(|object| object.len()) != Some(empty_families.len() + 4)
            || empty_families
                .iter()
                .any(|name| document[*name] != json!([]))
            || document["schemaVersion"].as_u64().is_none()
            || document["renderMetadataVersion"].as_u64().is_none()
            || document["plots"][0].as_object().map(|object| object.len()) != Some(2)
            || document["plots"][0]["id"] != json!(self.plot_id)
            || document["alerts"].as_array().map(|events| events.len()) != Some(alerts.len())
        {
            return Err(
                "complete public snapshot shape/defaults/nonfixture outputs diverged".into(),
            );
        }
        for (actual, expected) in document["alerts"]
            .as_array()
            .ok_or("missing alert array")?
            .iter()
            .zip(alerts)
        {
            if actual
                != &json!({"id":expected.id,"barIndex":expected.bar_index,"time":expected.time,
                "message":expected.message,"source":expected.source})
            {
                return Err("complete encoded event fields diverged".into());
            }
        }
        Ok(())
    }
    fn check_delta(
        &self,
        delta: &RuntimeChanges,
        revision: u64,
        visibility: StreamingVisibility,
        index: usize,
        price: u32,
        op: SeriesChangeOp,
        removed: &[AlertEvent],
        added: &[AlertEvent],
    ) -> Result<(), String> {
        if delta.revision != revision
            || delta.base_revision != revision - 1
            || delta.retained_from != 0
            || delta.visibility != visibility
        {
            return Err("public revision/origin/visibility sequence diverged".into());
        }
        if delta.series.len() != 1 {
            return Err("expected exactly one changed plot".into());
        }
        let series = &delta.series[0];
        if series.id != self.plot_id
            || series.family != SeriesFamily::Plot
            || series.op != op
            || series.start != index
            || series.fields.values.len() != 1
        {
            return Err("plot delta differs from independent bar fixture".into());
        }
        check_value(&series.fields.values[0], price)?;
        let expected = removed
            .iter()
            .rev()
            .map(|event| (EventAction::Remove, event))
            .chain(added.iter().map(|event| (EventAction::Add, event)));
        if delta.alerts.len() != removed.len() + added.len()
            || !delta
                .alerts
                .iter()
                .zip(expected)
                .all(|(actual, (action, event))| actual.action == action && &actual.event == event)
        {
            return Err("reverse remove then forward add event order/payload diverged".into());
        }
        if !delta.hlines.is_empty()
            || !delta.fills.is_empty()
            || !delta.drawings.is_empty()
            || delta.strategy.is_some()
            || !delta.diagnostics.is_empty()
        {
            return Err("unexpected nonfixture delta output".into());
        }
        Ok(())
    }
}
fn check_value(value: &PineValue, expected: u32) -> Result<(), String> {
    match value {
        PineValue::Float(actual) if actual.to_bits() == f64::from(expected).to_bits() => Ok(()),
        _ => Err(format!(
            "expected exact Float bits of {expected}, got {value:?}"
        )),
    }
}
fn profile_json(profile: &RuntimeProfile) -> Result<Value, Box<dyn std::error::Error>> {
    let encoded = public_runtime_profiled_result_json(&RuntimeResult::default(), profile);
    let mut value: Value = serde_json::from_str(&encoded)?;
    Ok(value["profile"].take())
}
enum Delivery<'a> {
    #[cfg(not(borrowed_delta))]
    Owned(RuntimeChanges, std::marker::PhantomData<&'a ()>),
    #[cfg(borrowed_delta)]
    Borrowed(&'a RuntimeChanges),
}
impl Delivery<'_> {
    fn changes(&self) -> &RuntimeChanges {
        match self {
            #[cfg(not(borrowed_delta))]
            Self::Owned(value, _) => value,
            #[cfg(borrowed_delta)]
            Self::Borrowed(value) => value,
        }
    }
}
fn deliver<'a>(
    runtime: &'a mut RealtimeRuntime<'_>,
    update: BarUpdate,
) -> Result<Delivery<'a>, RuntimeError> {
    #[cfg(not(borrowed_delta))]
    {
        runtime
            .apply_update(update)
            .map(|value| Delivery::Owned(value, std::marker::PhantomData))
    }
    #[cfg(borrowed_delta)]
    {
        runtime.apply_update_ref(update).map(Delivery::Borrowed)
    }
}
fn payload_path(receipt: &Path, role: &str) -> PathBuf {
    receipt.with_extension(format!("{role}.json"))
}
fn save_payload(
    receipt: &Path,
    role: &str,
    encoded: &str,
    files: &mut Vec<Value>,
) -> Result<(), Box<dyn std::error::Error>> {
    let path = payload_path(receipt, role);
    std::fs::write(&path, encoded)?;
    files.push(json!({"role":role,"path":path.to_string_lossy().replace('\\', "/")}));
    Ok(())
}
fn save_full(
    receipt: &Path,
    role: &str,
    runtime: &RealtimeRuntime<'_>,
    files: &mut Vec<Value>,
) -> Result<(), Box<dyn std::error::Error>> {
    save_payload(
        receipt,
        role,
        &public_runtime_result_view_json(&runtime.result_view()),
        files,
    )
}
fn check_replica(replica: &RuntimeReplica, runtime: &RealtimeRuntime<'_>) -> Result<(), String> {
    if replica.revision() != runtime.revision()
        || replica.retained_from() != 0
        || public_runtime_result_json(replica.result())
            != public_runtime_result_view_json(&runtime.result_view())
    {
        return Err("real RuntimeReplica diverged from full public runtime output".into());
    }
    Ok(())
}
fn apply_replica(replica: &mut RuntimeReplica, changes: &RuntimeChanges) -> Result<(), String> {
    if !replica.apply(changes).map_err(|error| error.message)?
        || replica.apply(changes).map_err(|error| error.message)?
    {
        return Err("real RuntimeReplica apply/replay contract diverged".into());
    }
    Ok(())
}
fn checked_single(
    runtime: &mut RealtimeRuntime<'_>,
    replica: &mut RuntimeReplica,
    fixture: &Fixture,
    receipt: &Path,
    files: &mut Vec<Value>,
    role: &str,
    update: BarUpdate,
    revision: u64,
    visibility: StreamingVisibility,
    index: usize,
    price: u32,
    op: SeriesChangeOp,
    removed: &[AlertEvent],
    added: &[AlertEvent],
) -> Result<Stage, Box<dyn std::error::Error>> {
    let runtime_ref = &mut *runtime;
    let (delivery, metric) = measure(move || deliver(runtime_ref, update));
    let delivery = delivery.map_err(|error| error.message)?;
    let changes = delivery.changes();
    fixture.check_delta(
        changes, revision, visibility, index, price, op, removed, added,
    )?;
    apply_replica(replica, changes)?;
    let encoded = public_runtime_changes_json(changes);
    save_payload(receipt, &format!("{role}-delta"), &encoded, files)?;
    // Delivery and all encoding/replica work are outside the timed call.
    drop(delivery);
    if runtime
        .last_changes()
        .map(public_runtime_changes_json)
        .as_deref()
        != Some(&encoded)
    {
        return Err("single-call cached last_changes differs from returned delta".into());
    }
    Ok(metric)
}
fn run() -> Result<(), Box<dyn std::error::Error>> {
    let arguments: Vec<_> = std::env::args().collect();
    if arguments.len() != 4 {
        return Err("usage: alert_probe COUNT PREFIX_CHARS RECEIPT.json".into());
    }
    let count: usize = arguments[1].parse()?;
    let prefix_chars: usize = arguments[2].parse()?;
    if !((count == 0 && prefix_chars == 0)
        || ([1, 16, 256].contains(&count) && [16, 4096, 16384].contains(&prefix_chars)))
    {
        return Err("fixture must be control(0,0) or count1/16/256 x prefix16/4096/16384".into());
    }
    let receipt = Path::new(&arguments[3]);
    let text = fixture_source(count, prefix_chars);
    let source = SourceFile::new("alert_probe.pine", &text);
    let (analysis, analyze) = measure(|| analyze_source(&source));
    if analysis
        .diagnostics
        .iter()
        .any(|diagnostic| diagnostic.severity == Severity::Error)
    {
        return Err(format!("{:?}", analysis.diagnostics).into());
    }
    let hir = analysis.hir.ok_or("missing HIR")?;
    // IDs come from source spans in analyzed HIR, never from runtime output.
    let mut call_sites = Vec::new();
    let mut alert_ids = Vec::new();
    let mut plot_ids = Vec::new();
    for site in &hir.call_site_sources {
        if site.source_id != 0 || site.library_key.is_some() {
            return Err("fixture callsite must belong to the direct source".into());
        }
        let expression = text
            .get(site.start..site.end)
            .ok_or("invalid HIR source span")?;
        if expression.starts_with("alert(") {
            alert_ids.push(site.call_site_id.0);
        }
        if expression.starts_with("plot(") {
            plot_ids.push(site.call_site_id.0);
        }
        call_sites.push(json!({"id":site.call_site_id.0,"sourceId":site.source_id,
            "libraryKey":site.library_key,"start":site.start,"end":site.end,"text":expression}));
    }
    if alert_ids.len() != usize::from(count != 0) || plot_ids.len() != 1 {
        return Err("unique alert/plot HIR source callsites required".into());
    }
    let fixture = Fixture {
        count,
        prefix: "x".repeat(prefix_chars),
        alert_id: alert_ids.first().copied(),
        plot_id: plot_ids[0],
    };
    let seed_bars = [bar(0, 100.0), bar(1, 101.0), bar(2, 102.0)];
    let mut runtime = RealtimeRuntime::new(&hir);
    let (seed, seed_metric) = measure(|| runtime.seed_historical_without_output(&seed_bars));
    seed.map_err(|error| error.message)?;
    fixture.check_view(runtime.result_view(), &[100, 101, 102], &[])?;
    fixture.check_view(runtime.confirmed_result_view(), &[100, 101, 102], &[])?;
    if runtime.revision() != 1 || runtime.last_changes().is_some() {
        return Err("seed revision/cache mismatch".into());
    }
    let seed_profile = profile_json(&runtime.profile())?;
    let mut files = Vec::with_capacity(34);
    save_full(receipt, "seed-full", &runtime, &mut files)?;
    let mut without = Vec::with_capacity(SAMPLES);
    let mut apply = Vec::with_capacity(SAMPLES);
    let mut clones = Vec::with_capacity(SAMPLES);
    let mut forming_checks = Vec::with_capacity(2 * SAMPLES);
    for sample in 0..SAMPLES {
        let price = 110 + (sample % 2) as u32;
        let events = fixture.events(3, price);
        let (updated, metric) =
            measure(|| runtime.update_without_output(BarUpdate::forming(bar(3, f64::from(price)))));
        updated.map_err(|error| error.message)?;
        fixture.check_view(runtime.result_view(), &[100, 101, 102, price], &events)?;
        fixture.check_view(runtime.confirmed_result_view(), &[100, 101, 102], &[])?;
        let revision = 2 + sample as u64;
        if runtime.revision() != revision || runtime.last_changes().is_some() {
            return Err("without-output revision/cache mismatch".into());
        }
        save_full(
            receipt,
            &format!("without-{sample}-full"),
            &runtime,
            &mut files,
        )?;
        forming_checks.push(json!({"method":"update_without_output","sample":sample,"revision":revision,
            "price":price,"previewAlerts":count,"confirmedAlerts":0,"confirmedBars":runtime.confirmed_bar_count(),
            "previewProfile":profile_json(&runtime.profile())?,"confirmedProfile":profile_json(&runtime.confirmed_profile())?,
            "fullPayloadMatchesFormula":true,"lastChangesIsNone":true}));
        without.push(stage_json(metric));
    }
    // Nine without-output calls advanced revisions. Start the real replica at
    // their current full preview/revision10, so its first delta has base10.
    let mut replica = RuntimeReplica::new(runtime.result(), runtime.revision());
    check_replica(&replica, &runtime)?;
    let mut previous = fixture.events(3, 110);
    for sample in 0..SAMPLES {
        let price = 120 + sample as u32;
        let current = fixture.events(3, price);
        let revision = 11 + sample as u64;
        let runtime_ref = &mut runtime;
        let (delivery, metric) =
            measure(move || deliver(runtime_ref, BarUpdate::forming(bar(3, f64::from(price)))));
        let delivery = delivery.map_err(|error| error.message)?;
        let changes = delivery.changes();
        fixture.check_delta(
            changes,
            revision,
            StreamingVisibility::Preview,
            3,
            price,
            SeriesChangeOp::ReplaceLast,
            &previous,
            &current,
        )?;
        let (clone, clone_metric) = measure(|| RuntimeChanges::clone(black_box(changes)));
        if &clone != changes {
            return Err("RuntimeChanges.clone changed payload".into());
        }
        apply_replica(&mut replica, changes)?;
        save_payload(
            receipt,
            &format!("apply-{sample}-delta"),
            &public_runtime_changes_json(changes),
            &mut files,
        )?;
        drop(delivery);
        if runtime.last_changes() != Some(&clone) {
            return Err("cached last_changes differs".into());
        }
        fixture.check_view(runtime.result_view(), &[100, 101, 102, price], &current)?;
        fixture.check_view(runtime.confirmed_result_view(), &[100, 101, 102], &[])?;
        check_replica(&replica, &runtime)?;
        save_full(
            receipt,
            &format!("apply-{sample}-full"),
            &runtime,
            &mut files,
        )?;
        forming_checks.push(json!({"method":if cfg!(borrowed_delta) {"apply_update_ref"} else {"apply_update"},
            "sample":sample,"revision":revision,"price":price,"previewAlerts":count,"confirmedAlerts":0,
            "confirmedBars":runtime.confirmed_bar_count(),"previewProfile":profile_json(&runtime.profile())?,
            "confirmedProfile":profile_json(&runtime.confirmed_profile())?,"fullPayloadMatchesFormula":true,
            "cachedChangesMatchReturned":true,"deltaMatchesFormula":true,"realReplicaMatchesFullOutput":true,
            "realReplicaReplayReturnsFalse":true,"returnedCloneMatchesOriginal":true}));
        drop(clone);
        previous = current;
        apply.push(stage_json(metric));
        clones.push(stage_json(clone_metric));
    }
    let confirmed_alerts = fixture.events(3, 140);
    let confirmed_metric = checked_single(
        &mut runtime,
        &mut replica,
        &fixture,
        receipt,
        &mut files,
        "confirmed",
        BarUpdate::confirmed(bar(3, 140.0)),
        20,
        StreamingVisibility::Confirmed,
        3,
        140,
        SeriesChangeOp::ReplaceLast,
        &previous,
        &confirmed_alerts,
    )?;
    fixture.check_view(
        runtime.result_view(),
        &[100, 101, 102, 140],
        &confirmed_alerts,
    )?;
    fixture.check_view(
        runtime.confirmed_result_view(),
        &[100, 101, 102, 140],
        &confirmed_alerts,
    )?;
    check_replica(&replica, &runtime)?;
    save_full(receipt, "confirmed-full", &runtime, &mut files)?;
    let confirmed_profile = profile_json(&runtime.profile())?;
    let historical_metric = checked_single(
        &mut runtime,
        &mut replica,
        &fixture,
        receipt,
        &mut files,
        "next-historical",
        BarUpdate::historical(bar(4, 150.0)),
        21,
        StreamingVisibility::Confirmed,
        4,
        150,
        SeriesChangeOp::Append,
        &[],
        &[],
    )?;
    fixture.check_view(
        runtime.result_view(),
        &[100, 101, 102, 140, 150],
        &confirmed_alerts,
    )?;
    fixture.check_view(
        runtime.confirmed_result_view(),
        &[100, 101, 102, 140, 150],
        &confirmed_alerts,
    )?;
    check_replica(&replica, &runtime)?;
    save_full(receipt, "next-historical-full", &runtime, &mut files)?;
    let historical_profile = profile_json(&runtime.profile())?;
    let next_alerts = fixture.events(5, 160);
    let forming_metric = checked_single(
        &mut runtime,
        &mut replica,
        &fixture,
        receipt,
        &mut files,
        "next-forming",
        BarUpdate::forming(bar(5, 160.0)),
        22,
        StreamingVisibility::Preview,
        5,
        160,
        SeriesChangeOp::Append,
        &[],
        &next_alerts,
    )?;
    let mut final_alerts = confirmed_alerts.clone();
    final_alerts.extend(next_alerts);
    fixture.check_view(
        runtime.result_view(),
        &[100, 101, 102, 140, 150, 160],
        &final_alerts,
    )?;
    fixture.check_view(
        runtime.confirmed_result_view(),
        &[100, 101, 102, 140, 150],
        &confirmed_alerts,
    )?;
    check_replica(&replica, &runtime)?;
    save_full(receipt, "next-forming-full", &runtime, &mut files)?;
    if files.len() != 34
        || runtime.revision() != 22
        || runtime.confirmed_bar_count() != 5
        || runtime.last_changes().map(|changes| changes.revision) != Some(22)
    {
        return Err("final sequence mismatch".into());
    }
    let result = json!({"probe":"publicAlertCopy","mode":if cfg!(borrowed_delta) {"borrowed"} else {"owned"},
        "count":count,"prefixChars":prefix_chars,"pineSource":text,"samplesPerRepeatedStage":SAMPLES,
        "seededRevision":1,"replicaSeedRevision":10,"publicRevision":runtime.revision(),"retainedFrom":0,
        "hirCallSites":call_sites,"alertCallSiteId":fixture.alert_id,"plotCallSiteId":fixture.plot_id,
        "stages":{"analyze":stage_json(analyze),"seedWithoutOutput":stage_json(seed_metric),
            "formingWithoutOutput":without,"formingApply":apply,"returnedChangesClone":clones,
            "confirmed":stage_json(confirmed_metric),"nextHistorical":stage_json(historical_metric),
            "nextFormingAfterConfirmation":stage_json(forming_metric)},
        "seedProfile":seed_profile,"confirmedProfile":confirmed_profile,"historicalProfile":historical_profile,
        "finalPreviewProfile":profile_json(&runtime.profile())?,"finalConfirmedProfile":profile_json(&runtime.confirmed_profile())?,
        "formingChecks":forming_checks,"rawPayloadFiles":files,
        "singleChecks":{"confirmed":{"revision":20,"previewAlerts":count,"confirmedAlerts":count,"confirmedBars":4},
            "nextHistorical":{"revision":21,"previewAlerts":count,"confirmedAlerts":count,"confirmedBars":5},
            "nextFormingAfterConfirmation":{"revision":22,"previewAlerts":2*count,"confirmedAlerts":count,"confirmedBars":5}},
        "allPublicPayloadsMatchIndependentFormula":true,"realReplicaApplyAndReplayVerified":true,
        "measurementScope":"Each named public call or RuntimeChanges::clone ends before its returned objects are dropped. Encoding, HIR inspection, full arithmetic oracles, profile sampling, real replica apply/replay and file writes are outside timing/allocation counters.",
        "limitations":"Allocator request/live-byte counters are not RSS or system transient realloc peaks. Prefix characters exclude the integer-price/loop-index suffix. Bar.time uses integer milliseconds with 60ms fixture spacing, not one-minute market bars. Owned/borrowed delivery differs while fixture and stage entry revisions match; borrowed has no before baseline. Final forming phase includes persistent-history partial-leaf COW after closed alerts; this is whole public-call attribution."});
    let encoded = serde_json::to_string(&result)?;
    std::fs::write(receipt, &encoded)?;
    println!("{encoded}");
    Ok(())
}
fn main() -> Result<(), Box<dyn std::error::Error>> {
    run()
}

alert_validation.py.content:
"""Independent fixture formulas and complete raw public-payload checks."""
from __future__ import annotations
import hashlib
import gzip
from pathlib import Path
import struct
from evidence_common import D, exact_payload, integer, loads, source

SAMPLES = 9
PROFILE_NAMES = ("seedProfile", "confirmedProfile", "historicalProfile",
                 "finalPreviewProfile", "finalConfirmedProfile")
FULL_ARRAYS = {"plotChars", "plotShapes", "plotArrows", "plotBars", "plotCandles",
               "bgColors", "barColors", "hlines", "fills", "labels", "lines", "lineFills",
               "polylines", "boxes", "tables", "diagnostics"}
FULL_KEYS = FULL_ARRAYS | {"schemaVersion", "renderMetadataVersion", "plots", "alerts"}
DELTA_KEYS = {"schemaVersion", "revision", "baseRevision", "retainedFrom", "visibility",
              "series", "hlines", "fills", "drawings", "alerts", "diagnostics"}
TOP = {"probe", "mode", "count", "prefixChars", "pineSource", "samplesPerRepeatedStage",
       "seededRevision", "replicaSeedRevision", "publicRevision", "retainedFrom", "hirCallSites",
       "alertCallSiteId", "plotCallSiteId", "stages", *PROFILE_NAMES, "formingChecks",
       "rawPayloadFiles", "singleChecks", "allPublicPayloadsMatchIndependentFormula",
       "realReplicaApplyAndReplayVerified", "measurementScope", "limitations"}


def cases():
    return [{"name":"noalerts", "count":0, "prefixChars":0}] + [
        {"name":f"count{count}_prefix{chars}", "count":count, "prefixChars":chars}
        for count in (1,16,256) for chars in (16,4096,16384)]


def pine_source(case):
    text = '//@version=6\nindicator("alert copy probe")\n'
    if case["count"]:
        text += ('if barstate.isrealtime\n'
                 f'    prefix = str.repeat("x", {case["prefixChars"]})\n'
                 f'    for loopindex = 0 to {case["count"]-1}\n'
                 '        alert(prefix + "|" + str.tostring(close) + "|" + str.tostring(loopindex), alert.freq_all)\n')
    return text + 'plot(close)\n'


def prepare_case(case):
    text = pine_source(case)
    return {**case,"pineSource":text,"source":source(D/f'alert-{case["name"]}.pine',text)}


def profile(value, fields, bars):
    if not isinstance(value,dict) or sorted(value) != fields:
        raise ValueError("Incomplete or unexpected public profile schema")
    for name, item in value.items():
        if name == "historyRetentionMode":
            if item not in {"staticTrimmed","dynamicFull","maxBarsBack"}:
                raise ValueError("Invalid history retention mode")
        elif item is None and name in {"historyMaxBarsBack","historyDynamicRetentionMaxMissedOffset"}:
            continue
        elif name == "historyHasDynamicOffsets":
            if type(item) is not bool:
                raise ValueError("Invalid dynamic-history flag")
        else:
            integer(item,0)
    if (value["bars"] != bars or value["plots"] != 1 or value["plotValues"] != bars
            or value["valuewhenStateSlots"] != 0
            or value["valuewhenStateValues"] != 0 or value["valuewhenStateValueCapacity"] != 0):
        raise ValueError("Independent bar/absent-valuewhen profile counters differ")


def call_ids(metrics, case):
    text = pine_source(case)
    sites = metrics["hirCallSites"]
    if not isinstance(sites,list) or not sites:
        raise ValueError("Missing original HIR source spans")
    identifiers, alert, plot = set(),[],[]
    for site in sites:
        if set(site) != {"id","sourceId","libraryKey","start","end","text"}:
            raise ValueError("Unexpected HIR callsite metadata")
        identifier,start,end = integer(site["id"],0),integer(site["start"],0),integer(site["end"],0)
        if (identifier in identifiers or end <= start or end > len(text)
                or site["sourceId"] != 0 or site["libraryKey"] is not None or site["text"] != text[start:end]):
            raise ValueError("Invalid or duplicate original HIR source span")
        identifiers.add(identifier)
        if site["text"].startswith("alert("):
            alert.append(identifier)
        if site["text"].startswith("plot("):
            plot.append(identifier)
    if len(alert)!=int(case["count"]!=0) or len(plot)!=1:
        raise ValueError("Unique source-defined alert/plot callsite required")
    alert_id = alert[0] if alert else None
    if metrics["alertCallSiteId"]!=alert_id or metrics["plotCallSiteId"]!=plot[0]:
        raise ValueError("Published callsite IDs diverge from HIR/source")
    return alert_id,plot[0]


def validate(metrics, case, fields, mode="owned"):
    if not isinstance(metrics,dict) or set(metrics)!=TOP:
        raise ValueError("Unknown or missing alert receipt field")
    expected = {"probe":"publicAlertCopy", "mode":mode,"count":case["count"],
                "prefixChars":case["prefixChars"],"pineSource":pine_source(case),
                "samplesPerRepeatedStage":SAMPLES,"seededRevision":1,"replicaSeedRevision":10,
                "publicRevision":22,"retainedFrom":0,"allPublicPayloadsMatchIndependentFormula":True,
                "realReplicaApplyAndReplayVerified":True}
    for name,value in expected.items():
        if type(metrics[name]) is not type(value) or metrics[name]!=value:
            raise ValueError("Unexpected alert fixture field: "+name)
    call_ids(metrics,case)
    for name,bars in zip(PROFILE_NAMES,(3,4,5,6,5)):
        profile(metrics[name],fields,bars)
    checks=metrics["formingChecks"]
    if not isinstance(checks,list) or len(checks)!=18:
        raise ValueError("Expected all 18 forming correctness checks")
    for index,row in enumerate(checks):
        sample=index%SAMPLES
        without=index<SAMPLES
        expected = {"method":"update_without_output" if without else ("apply_update_ref" if mode=="borrowed" else "apply_update"),
                    "sample":sample,"revision":2+index,"price":110+sample%2 if without else 120+sample,
                    "previewAlerts":case["count"],"confirmedAlerts":0,"confirmedBars":3,
                    "fullPayloadMatchesFormula":True}
        if without:
            expected["lastChangesIsNone"]=True
        else:
            expected.update(cachedChangesMatchReturned=True,deltaMatchesFormula=True,
                            realReplicaMatchesFullOutput=True,realReplicaReplayReturnsFalse=True,
                            returnedCloneMatchesOriginal=True)
        if set(row)!=set(expected)|{"previewProfile","confirmedProfile"}:
            raise ValueError("Unexpected forming check fields")
        for name,value in expected.items():
            if type(row[name]) is not type(value) or row[name]!=value:
                raise ValueError("Independent forming check differs: "+name)
        profile(row["previewProfile"],fields,4)
        profile(row["confirmedProfile"],fields,3)
    k=case["count"]
    if metrics["singleChecks"]!={
        "confirmed":{"revision":20,"previewAlerts":k,"confirmedAlerts":k,"confirmedBars":4},
        "nextHistorical":{"revision":21,"previewAlerts":k,"confirmedAlerts":k,"confirmedBars":5},
        "nextFormingAfterConfirmation":{"revision":22,"previewAlerts":2*k,"confirmedAlerts":k,"confirmedBars":5}}:
        raise ValueError("Independent final confirmed/preview counts differ")
    return {"fullPublicProfiles":41,"all102ProfileFieldsPreserved":True,
            "hirIDsBoundToDirectSourceSpans":True,"exactFormulaChecks":True,
            "replicaSeedRevision":10,"publicRevision":22,"retainedFrom":0}


def event(case, identifier, index, price, loopindex):
    return {"id":identifier,"barIndex":index,"time":1_700_000_000+index*60,
            "message":"x"*case["prefixChars"]+f"|{price}|{loopindex}","source":"alert"}


def events(case, identifier, index, price):
    return [event(case,identifier,index,price,loopindex) for loopindex in range(case["count"])]


def float_values(actual, expected):
    if not isinstance(actual,list) or len(actual)!=len(expected):
        raise ValueError("Incomplete plotted history")
    for value, price in zip(actual,expected):
        if type(value) not in (int,float) or struct.pack("!d",float(value))!=struct.pack("!d",float(price)):
            raise ValueError("Independent plot Float bits differ")


def full_payload(value, prices, expected_events, plot_id):
    if not isinstance(value,dict) or set(value)!=FULL_KEYS:
        raise ValueError("Unexpected full public snapshot schema")
    integer(value["schemaVersion"],1)
    integer(value["renderMetadataVersion"],1)
    if any(value[name]!=[] for name in FULL_ARRAYS):
        raise ValueError("Unexpected nonfixture output")
    if not isinstance(value["plots"],list) or len(value["plots"])!=1:
        raise ValueError("Expected one complete fixture plot")
    plot=value["plots"][0]
    if set(plot)!={"id","values"} or plot["id"]!=plot_id:
        raise ValueError("Unexpected plot identity/metadata/default omission")
    float_values(plot["values"],prices)
    if value["alerts"]!=expected_events:
        raise ValueError("Complete ordered alert events differ from formula")


def delta_payload(value, revision, visibility, index, price, op, removed, added, plot_id):
    if not isinstance(value,dict) or set(value)!=DELTA_KEYS:
        raise ValueError("Unexpected complete public delta schema")
    if (value["revision"]!=revision or value["baseRevision"]!=revision-1
            or value["retainedFrom"]!=0 or value["visibility"]!=visibility):
        raise ValueError("Delta revision/base/origin/visibility differs")
    integer(value["schemaVersion"],1)
    if any(value[name]!=[] for name in ("hlines","fills","drawings","diagnostics")):
        raise ValueError("Unexpected nonfixture delta")
    if not isinstance(value["series"],list) or len(value["series"])!=1:
        raise ValueError("Expected one changed plot")
    series=value["series"][0]
    # Headers are absent for a seeded plot; colors can carry the explicit Na
    # when append/replace fields are populated, and must then equal [null].
    if not {"family","id","op","start","values"}<=set(series) or not set(series)<={"family","id","op","start","values","colors"}:
        raise ValueError("Unexpected fixture plot delta fields")
    if (series["family"]!="plot" or series["id"]!=plot_id or series["op"]!=op
            or series["start"]!=index or ("colors" in series and series["colors"]!=[None])):
        raise ValueError("Plot delta operation/start/identity differs")
    float_values(series["values"],[price])
    expected=[{"action":"remove","event":item} for item in reversed(removed)] + [
        {"action":"add","event":item} for item in added]
    if value["alerts"]!=expected:
        raise ValueError("Reverse-remove/forward-add ordered complete events differ")


def payload_roles():
    return ["seed-full"]+[f"without-{sample}-full" for sample in range(SAMPLES)]+[
        role for sample in range(SAMPLES) for role in (f"apply-{sample}-delta",f"apply-{sample}-full")]+[
        "confirmed-delta","confirmed-full","next-historical-delta","next-historical-full","next-forming-delta","next-forming-full"]


def load_payload(path,outdir):
    path=Path(path).resolve()
    if path.is_file():
        return exact_payload(path,outdir)
    # Audit can recheck formulas directly from losslessly compressed outputs;
    # the result receipt additionally binds decoded bytes/SHA via decode_payload.
    compressed=path.with_suffix(path.suffix+".gz")
    if (path.parent!=Path(outdir).resolve() or path.suffix!=".json"
            or compressed.is_symlink() or not compressed.is_file()):
        raise ValueError("Missing exact raw/gzip payload within its own receipt directory")
    return gzip.decompress(compressed.read_bytes())


def validate_payloads(metrics,case,outdir,receipt=None):
    rows=metrics["rawPayloadFiles"]
    roles=payload_roles()
    if not isinstance(rows,list) or len(rows)!=34 or [row.get("role") for row in rows]!=roles:
        raise ValueError("Expected all 34 unique ordered raw payload roles")
    alert_id,plot_id=call_ids(metrics,case)
    result=[]
    for row,role in zip(rows,roles):
        if set(row)!={"role","path"}:
            raise ValueError("Unexpected raw payload metadata")
        path=Path(row["path"])
        if receipt is not None and path.resolve()!=receipt.with_suffix(f".{role}.json").resolve():
            raise ValueError("Payload path does not match exact process receipt role")
        raw=load_payload(path,outdir)
        value=loads(raw)
        if role=="seed-full":
            full_payload(value,[100,101,102],[],plot_id)
        elif role.startswith("without-"):
            sample=int(role.split("-")[1]);price=110+sample%2
            full_payload(value,[100,101,102,price],events(case,alert_id,3,price),plot_id)
        elif role.startswith("apply-"):
            sample=int(role.split("-")[1]);price=120+sample
            current=events(case,alert_id,3,price)
            if role.endswith("-full"):
                full_payload(value,[100,101,102,price],current,plot_id)
            else:
                previous=events(case,alert_id,3,110 if sample==0 else price-1)
                delta_payload(value,11+sample,"preview",3,price,"replaceLast",previous,current,plot_id)
        else:
            closed=events(case,alert_id,3,140)
            if role=="confirmed-delta":
                delta_payload(value,20,"confirmed",3,140,"replaceLast",events(case,alert_id,3,128),closed,plot_id)
            elif role=="confirmed-full":
                full_payload(value,[100,101,102,140],closed,plot_id)
            elif role=="next-historical-delta":
                delta_payload(value,21,"confirmed",4,150,"append",[],[],plot_id)
            elif role=="next-historical-full":
                full_payload(value,[100,101,102,140,150],closed,plot_id)
            elif role=="next-forming-delta":
                delta_payload(value,22,"preview",5,160,"append",[],events(case,alert_id,5,160),plot_id)
            elif role=="next-forming-full":
                full_payload(value,[100,101,102,140,150,160],closed+events(case,alert_id,5,160),plot_id)
        result.append({"role":role,"path":path.resolve().as_posix(),"originalSha256":hashlib.sha256(raw).hexdigest(),
                       "originalBytes":len(raw),"completeJSONMatchesIndependentFormula":True})
    return result


def comparison_value(metrics):
    return {**{name:metrics[name] for name in PROFILE_NAMES},
            "formingChecks":[{key:value for key,value in row.items() if key!="method"}
                             for row in metrics["formingChecks"]],
            "hirCallSites":metrics["hirCallSites"],"singleChecks":metrics["singleChecks"],
            "alertCallSiteId":metrics["alertCallSiteId"],"plotCallSiteId":metrics["plotCallSiteId"]}

budget_probe.rs.content:
// Default-budget before/after attribution. This entry and common include use
// only the public API available in the sealed 557c48b06 baseline.
include!("budget_probe_common.rs");

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let arguments: Vec<_> = std::env::args().collect();
    if arguments.len() != 4 {
        return Err("usage: budget_probe CALL_SITES BARS RECEIPT.json".into());
    }
    let call_sites: usize = arguments[1].parse()?;
    let count: usize = arguments[2].parse()?;
    if ![1, 8, 64].contains(&call_sites) || ![10_000, 20_000].contains(&count) {
        return Err(
            "qualification requires CALL_SITES in {1,8,64} and BARS in {10000,20000}".into(),
        );
    }
    let receipt_path = Path::new(&arguments[3]);
    let source_text = script(call_sites);
    let source = SourceFile::new("budget_probe.pine", source_text.clone());
    let (analysis, analyze_metric) = measure(|| analyze_source(&source));
    if analysis
        .diagnostics
        .iter()
        .any(|diagnostic| diagnostic.severity == Severity::Error)
    {
        return Err(format!("{:?}", analysis.diagnostics).into());
    }
    let hir = analysis.hir.ok_or("missing HIR")?;
    let bars: Vec<_> = (0..count).map(|index| bar(index, close(index))).collect();
    let mut history = HistoricalRuntime::new(&hir);
    let (seeded, seed_metric) = measure(|| history.append_bars(&bars));
    seeded.map_err(|error| error.message)?;
    let history_profile = history.profile();
    check_profile(&history_profile, call_sites, count)?;
    let seed_oracle = check_all(history.result_view(), call_sites, count, None)?;
    let mut raw_files = vec![save_snapshot(receipt_path, "seed", &history.result_view())?];
    let mut clone_samples = Vec::with_capacity(SAMPLES);
    let mut clone_checks = Vec::with_capacity(SAMPLES);
    for sample in 0..SAMPLES {
        let (checkpoint, metric) = measure(|| black_box(&history).clone());
        let checked = check_all(checkpoint.result_view(), call_sites, count, None)?;
        check_profile(&checkpoint.profile(), call_sites, count)?;
        if checked != seed_oracle {
            return Err("public historical clone changed plot history".into());
        }
        clone_checks.push(json!({"sample": sample, "allValuesMatchDirectOracle": true,
            "fnv1a64ValueBitsLe": checked["fnv1a64ValueBitsLe"],
            "profile": profile_json(&checkpoint.profile())?}));
        // The cloned runtime remains alive until all reads end; its disposal
        // is outside the clone allocation and Instant boundaries.
        drop(checkpoint);
        clone_samples.push(stage_json(metric));
    }
    if history.profile() != history_profile {
        return Err("reading clones changed original historical profile".into());
    }
    drop(history);

    let mut realtime = RealtimeRuntime::new(&hir);
    let (seeded, realtime_seed_metric) = measure(|| realtime.seed_historical_without_output(&bars));
    seeded.map_err(|error| error.message)?;
    let realtime_seed_profile = realtime.profile();
    check_profile(&realtime_seed_profile, call_sites, count)?;
    if check_all(realtime.result_view(), call_sites, count, None)? != seed_oracle {
        return Err("historical and realtime seed values diverged".into());
    }
    let seeded_revision = realtime.revision();
    let mut without_samples = Vec::with_capacity(SAMPLES);
    let mut apply_samples = Vec::with_capacity(SAMPLES);
    let mut forming_checks = Vec::with_capacity(SAMPLES * 2);
    for sample in 0..SAMPLES {
        let ticks = quarter_ticks(count) + (sample + 1) as u64;
        let (updated, metric) = measure(|| {
            realtime.update_without_output(BarUpdate::forming(bar(count, ticks as f64 / 4.0)))
        });
        updated.map_err(|error| error.message)?;
        let tail_bits = check_tail(
            realtime.result_view(),
            call_sites,
            count + 1,
            Some((count, ticks)),
        )?;
        check_profile(&realtime.profile(), call_sites, count + 1)?;
        if realtime.confirmed_profile() != realtime_seed_profile
            || realtime.last_changes().is_some()
        {
            return Err(
                "forming without-output changed committed profile or retained changes".into(),
            );
        }
        if realtime.revision() != seeded_revision + sample as u64 + 1 {
            return Err("without-output revision sequence diverged".into());
        }
        forming_checks.push(json!({"method": "update_without_output", "sample": sample,
            "replacementQuarterTicks": ticks, "oracleBits": format!("{tail_bits:016x}"),
            "previewEvents": call_sites*(count+1), "confirmedEvents": call_sites*count,
            "revision": realtime.revision(), "profile": profile_json(&realtime.profile())?,
            "confirmedProfile": profile_json(&realtime.confirmed_profile())?}));
        without_samples.push(stage_json(metric));
    }
    for sample in 0..SAMPLES {
        let ticks = quarter_ticks(count) - (sample + 1) as u64;
        let (changes, metric) =
            measure(|| realtime.apply_update(BarUpdate::forming(bar(count, ticks as f64 / 4.0))));
        let changes = changes.map_err(|error| error.message)?;
        let tail_bits = check_tail(
            realtime.result_view(),
            call_sites,
            count + 1,
            Some((count, ticks)),
        )?;
        check_profile(&realtime.profile(), call_sites, count + 1)?;
        if realtime.confirmed_profile() != realtime_seed_profile
            || realtime.last_changes() != Some(&changes)
        {
            return Err(
                "forming apply changed committed profile or disagreed with last_changes".into(),
            );
        }
        if realtime.revision() != seeded_revision + (SAMPLES + sample + 1) as u64 {
            return Err("apply revision sequence diverged".into());
        }
        let path = payload_path(receipt_path, &format!("forming-apply-{sample}"));
        std::fs::write(&path, public_runtime_changes_json(&changes))?;
        raw_files.push(path.to_string_lossy().into_owned());
        forming_checks.push(json!({"method": "apply_update", "sample": sample,
            "replacementQuarterTicks": ticks, "oracleBits": format!("{tail_bits:016x}"),
            "previewEvents": call_sites*(count+1), "confirmedEvents": call_sites*count,
            "revision": realtime.revision(), "profile": profile_json(&realtime.profile())?,
            "confirmedProfile": profile_json(&realtime.confirmed_profile())?}));
        // Actual public delta construction is timed; encoding, comparisons,
        // file writes and caller-owned returned-delta disposal are not.
        drop(changes);
        apply_samples.push(stage_json(metric));
    }
    let confirmed_ticks = quarter_ticks(count) + 3;
    let (confirmed, confirm_metric) = measure(|| {
        realtime.update_without_output(BarUpdate::confirmed(bar(
            count,
            confirmed_ticks as f64 / 4.0,
        )))
    });
    confirmed.map_err(|error| error.message)?;
    check_profile(&realtime.profile(), call_sites, count + 1)?;
    if realtime.profile() != realtime.confirmed_profile() {
        return Err("confirmed live profile diverged from committed state".into());
    }
    let confirmed_oracle = check_all(
        realtime.result_view(),
        call_sites,
        count + 1,
        Some((count, confirmed_ticks)),
    )?;
    let confirmed_profile = profile_json(&realtime.profile())?;
    raw_files.push(save_snapshot(
        receipt_path,
        "confirmed",
        &realtime.result_view(),
    )?);
    let (appended, historical_metric) = measure(|| {
        realtime.update_without_output(BarUpdate::historical(bar(count + 1, close(count + 1))))
    });
    appended.map_err(|error| error.message)?;
    check_profile(&realtime.profile(), call_sites, count + 2)?;
    if realtime.profile() != realtime.confirmed_profile() {
        return Err("next historical live profile diverged from committed state".into());
    }
    let final_oracle = check_all(
        realtime.result_view(),
        call_sites,
        count + 2,
        Some((count, confirmed_ticks)),
    )?;
    let final_profile = profile_json(&realtime.profile())?;
    raw_files.push(save_snapshot(
        receipt_path,
        "next-historical",
        &realtime.result_view(),
    )?);
    if realtime.revision() != seeded_revision + (2 * SAMPLES + 2) as u64 {
        return Err("final public revision sequence diverged".into());
    }
    let receipt = json!({
        "probe": "publicDefaultValuewhenBudgetCompatibility", "callSites": call_sites, "bars": count,
        "pineSource": source_text, "samplesPerRepeatedStage": SAMPLES, "configuredBudget": false,
        "stages": {"analyze": stage_json(analyze_metric), "historicalSeed": stage_json(seed_metric),
            "historicalClone": clone_samples, "realtimeSeedWithoutOutput": stage_json(realtime_seed_metric),
            "formingWithoutOutput": without_samples, "formingApplyUpdate": apply_samples,
            "confirmedWithoutOutput": stage_json(confirm_metric), "nextHistoricalWithoutOutput": stage_json(historical_metric)},
        "seedProfile": profile_json(&history_profile)?, "realtimeSeedProfile": profile_json(&realtime_seed_profile)?,
        "confirmedProfile": confirmed_profile,
        "finalProfile": final_profile, "cloneChecks": clone_checks, "formingChecks": forming_checks,
        "seedOracle": seed_oracle, "confirmedOracle": confirmed_oracle, "finalOracle": final_oracle,
        "seededRevision": seeded_revision, "publicRevision": realtime.revision(), "rawPayloadFiles": raw_files,
        "allowedBeforeAfterProfileDifferences": [], "profileFieldCount": PROFILE_FIELDS,
        "logicalValues": {"seed": call_sites*count, "preview": call_sites*(count+1),
            "confirmed": call_sites*(count+1), "final": call_sites*(count+2)},
        "confirmedReplacementQuarterTicks": confirmed_ticks,
        "oracle": "event_index=i-i%5000; sum quarter numerator=K*(400+event_index)+2*K*(K-1); replacement uses integer quarter ticks; full seed, every clone, confirmed and next histories checked by Float IEEE bits",
        "measurementScope": "one public call per sample; caller drop, profile, oracle, encoders and file writes excluded; runtime internal replacement/disposal remains inside the named call",
        "allocatorScope": "System layout-request accounting, cumulative successful allocated/reallocated bytes and calls; peakAdditionalLiveBytes above each phase entry, signed liveDeltaBytes at exit; realloc counts new size once after removing old live size; not allocator residency or process RSS",
        "limits": "default constructors only, no limits setter or new getter; historical/current logical event counters are public profile observations; configured-budget rejection correctness is qualified separately",
        "limitations": "ordinary numeric source, one indicator plot; whole-runtime clone/update attribution, no isolated event-counter cost, no request evaluator/strategy/fill performance, no process RSS, no elapsed disposal qualification",
    });
    let encoded = serde_json::to_string(&receipt)?;
    std::fs::write(receipt_path, &encoded)?;
    println!("{encoded}");
    Ok(())
}

budget_probe_common.rs.content:
// Public baseline-compatible probe helpers. Keep this include and entry source
// identical for both binaries; no new limits API or private runtime state here.
use pine_runtime::*;
use pine_sema::analyze_source;
use pine_syntax::{Severity, SourceFile};
use serde_json::{Value, json};
use std::alloc::{GlobalAlloc, Layout, System};
use std::hint::black_box;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicUsize, Ordering::Relaxed};
use std::time::Instant;

const SAMPLES: usize = 9;
const PROFILE_FIELDS: usize = 102;
struct CountingAllocator;
static LIVE: AtomicUsize = AtomicUsize::new(0);
static PEAK: AtomicUsize = AtomicUsize::new(0);
static ALLOCATED: AtomicUsize = AtomicUsize::new(0);
static ALLOCS: AtomicUsize = AtomicUsize::new(0);
fn allocation(size: usize) {
    ALLOCATED.fetch_add(size, Relaxed);
    ALLOCS.fetch_add(1, Relaxed);
    let live = LIVE.fetch_add(size, Relaxed) + size;
    PEAK.fetch_max(live, Relaxed);
}
unsafe impl GlobalAlloc for CountingAllocator {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        let result = unsafe { System.alloc(layout) };
        if !result.is_null() {
            allocation(layout.size());
        }
        result
    }
    unsafe fn dealloc(&self, pointer: *mut u8, layout: Layout) {
        LIVE.fetch_sub(layout.size(), Relaxed);
        unsafe { System.dealloc(pointer, layout) }
    }
    unsafe fn realloc(&self, pointer: *mut u8, layout: Layout, size: usize) -> *mut u8 {
        let result = unsafe { System.realloc(pointer, layout, size) };
        if !result.is_null() {
            LIVE.fetch_sub(layout.size(), Relaxed);
            allocation(size);
        }
        result
    }
}
#[global_allocator]
static GLOBAL: CountingAllocator = CountingAllocator;

#[derive(Clone, Copy)]
struct Stage {
    ms: f64,
    bytes: usize,
    count: usize,
    peak: usize,
    live_delta: i64,
}
fn measure<T>(operation: impl FnOnce() -> T) -> (T, Stage) {
    let initial = LIVE.load(Relaxed);
    PEAK.store(initial, Relaxed);
    let bytes = ALLOCATED.load(Relaxed);
    let count = ALLOCS.load(Relaxed);
    let started = Instant::now();
    let result = black_box(operation());
    let ms = started.elapsed().as_secs_f64() * 1000.0;
    (
        result,
        Stage {
            ms,
            bytes: ALLOCATED.load(Relaxed) - bytes,
            count: ALLOCS.load(Relaxed) - count,
            peak: PEAK.load(Relaxed).saturating_sub(initial),
            live_delta: LIVE.load(Relaxed) as i64 - initial as i64,
        },
    )
}
fn stage_json(stage: Stage) -> Value {
    json!({"ms": stage.ms, "allocatedBytes": stage.bytes, "allocations": stage.count,
        "peakAdditionalLiveBytes": stage.peak, "liveDeltaBytes": stage.live_delta})
}
fn quarter_ticks(index: usize) -> u64 {
    400 + index as u64
}
fn close(index: usize) -> f64 {
    quarter_ticks(index) as f64 / 4.0
}
fn bar(index: usize, price: f64) -> Bar {
    Bar {
        time: 1_700_000_000 + index as i64 * 60,
        open: price,
        high: price + 1.0,
        low: price - 1.0,
        close: price,
        volume: 100.0,
    }
}
fn script(call_sites: usize) -> String {
    let mut source =
        String::from("//@version=6\nindicator(\"default valuewhen budget compatibility\")\n");
    for call_index in 0..call_sites {
        source.push_str(&format!(
            "v{call_index} = ta.valuewhen(true, close + {call_index}, bar_index % 5000)\n"
        ));
    }
    source.push_str("plot(");
    for call_index in 0..call_sites {
        if call_index != 0 {
            source.push_str(" + ");
        }
        source.push_str(&format!("v{call_index}"));
    }
    source.push_str(")\n");
    source
}
// No event queue or runtime outputs are consulted. Every source and sum is
// exactly representable: the independent integer-quarter numerator remains
// far below 2^53 even for K=64 and N=20002.
fn oracle(call_sites: usize, index: usize, replacement: Option<(usize, u64)>) -> f64 {
    let event_index = index - index % 5000;
    let ticks = match replacement {
        Some((at, ticks)) if event_index == at => ticks,
        _ => quarter_ticks(event_index),
    };
    let calls = call_sites as u64;
    (calls * ticks + 2 * calls * (calls - 1)) as f64 / 4.0
}
fn verify_value(actual: &PineValue, expected: f64) -> Result<u64, String> {
    match actual {
        PineValue::Float(value) if value.to_bits() == expected.to_bits() => Ok(value.to_bits()),
        _ => Err(format!(
            "direct integer-quarter oracle mismatch: actual={actual:?}, expected={expected:?}"
        )),
    }
}
fn check_tail(
    view: RuntimeResultView<'_>,
    call_sites: usize,
    bars: usize,
    replacement: Option<(usize, u64)>,
) -> Result<u64, String> {
    if view.plots.len() != 1 || view.plots[0].values.len() != bars {
        return Err("fixture must expose one complete plot history".into());
    }
    let last = view.plots[0].values.iter().last().ok_or("empty plot")?;
    verify_value(last, oracle(call_sites, bars - 1, replacement))
}
fn check_all(
    view: RuntimeResultView<'_>,
    call_sites: usize,
    bars: usize,
    replacement: Option<(usize, u64)>,
) -> Result<Value, String> {
    if view.plots.len() != 1 || view.plots[0].values.len() != bars {
        return Err("fixture must expose one complete plot history".into());
    }
    let mut hash = 0xcbf29ce484222325_u64;
    for (index, value) in view.plots[0].values.iter().enumerate() {
        let bits = verify_value(value, oracle(call_sites, index, replacement))?;
        for byte in bits.to_le_bytes() {
            hash = (hash ^ u64::from(byte)).wrapping_mul(0x100000001b3);
        }
    }
    Ok(
        json!({"plotValues": bars, "naValues": 0, "allValuesMatchDirectOracle": true,
        "fnv1a64ValueBitsLe": format!("{hash:016x}")}),
    )
}
fn profile_json(profile: &RuntimeProfile) -> Result<Value, Box<dyn std::error::Error>> {
    let encoded = public_runtime_profiled_result_json(&RuntimeResult::default(), profile);
    let mut value: Value = serde_json::from_str(&encoded)?;
    let profile = value["profile"].take();
    if profile.as_object().ok_or("profile is not an object")?.len() != PROFILE_FIELDS {
        return Err("public profile schema must contain exactly 102 fields".into());
    }
    Ok(profile)
}
fn check_profile(profile: &RuntimeProfile, call_sites: usize, bars: usize) -> Result<(), String> {
    if profile.bars != bars
        || profile.valuewhen_state_slots != call_sites
        || profile.valuewhen_state_values != call_sites * bars
        || profile.strategy_script_passes != 0
        || profile.strategy_recalculation_passes != 0
    {
        return Err(format!("bar/event/callsite counters diverged: {profile:?}"));
    }
    Ok(())
}
fn payload_path(receipt: &Path, suffix: &str) -> PathBuf {
    receipt.with_extension(format!("{suffix}.json"))
}
fn save_snapshot(
    receipt: &Path,
    suffix: &str,
    view: &RuntimeResultView<'_>,
) -> Result<String, Box<dyn std::error::Error>> {
    let path = payload_path(receipt, suffix);
    std::fs::write(&path, public_runtime_result_view_json(view))?;
    Ok(path.to_string_lossy().into_owned())
}

budget_validation.py.content:
"""Default-budget fixture/oracle definitions only; never build/link/run probes.

All integer-quarter formulas below are independent of runtime event storage.
The coordinator owns process identities, scheduling, stage metrics, compression,
and before/after equality. This module performs no work merely on import.
"""
from __future__ import annotations

import gzip
import hashlib
import json
import math
from pathlib import Path
import struct

D = Path(__file__).resolve().parent
SAMPLES = 9
PROFILE_FIELD_COUNT = 102
SINGLE_STAGES = {"analyze", "historicalSeed", "realtimeSeedWithoutOutput",
                 "confirmedWithoutOutput", "nextHistoricalWithoutOutput"}
REPEATED_STAGES = {"historicalClone", "formingWithoutOutput", "formingApplyUpdate"}
METRIC_FIELDS = {"ms", "allocatedBytes", "allocations", "peakAdditionalLiveBytes", "liveDeltaBytes"}
PROFILE_FIELDS = ("seedProfile", "realtimeSeedProfile", "confirmedProfile", "finalProfile")
TOP = {"probe", "callSites", "bars", "pineSource", "samplesPerRepeatedStage", "configuredBudget",
       "stages", *PROFILE_FIELDS, "cloneChecks", "formingChecks", "seedOracle", "confirmedOracle",
       "finalOracle", "seededRevision", "publicRevision", "rawPayloadFiles",
       "allowedBeforeAfterProfileDifferences", "profileFieldCount", "logicalValues",
       "confirmedReplacementQuarterTicks", "oracle", "measurementScope", "allocatorScope",
       "limits", "limitations"}
FNV_OFFSET, FNV_MULTIPLIER, U64 = 0xCBF29CE484222325, 0x100000001B3, (1 << 64) - 1


def cases():
    return [{"name": f"budget-k{calls}-n{bars}", "count": calls, "callSites": calls, "bars": bars}
            for calls in (1, 8, 64) for bars in (10_000, 20_000)]


def pine_source(calls):
    if calls not in (1, 8, 64):
        raise ValueError("unexpected independent call-site count")
    header = '//@version=6\nindicator("default valuewhen budget compatibility")\n'
    declarations = ''.join(f'v{index} = ta.valuewhen(true, close + {index}, bar_index % 5000)\n'
                           for index in range(calls))
    return header + declarations + 'plot(' + ' + '.join(f'v{index}' for index in range(calls)) + ')\n'


def prepare_case(case):
    wanted = next((item for item in cases() if item["name"] == case.get("name")), None)
    if wanted is None or any(case.get(key) != value for key, value in wanted.items()):
        raise ValueError("case does not belong to the frozen six-case matrix")
    text = pine_source(wanted["count"])
    directory = D / "fixtures"
    directory.mkdir(exist_ok=True)
    path = directory / (wanted["name"] + ".pine")
    raw = text.encode("utf-8")
    path.write_bytes(raw)
    return {**wanted, "pineSource": text,
            "source": {"path": str(path), "sha256": hashlib.sha256(raw).hexdigest(), "bytes": len(raw)}}


def integer(value):
    if type(value) is not int:
        raise ValueError("expected integer")
    return value


def value_bits(value):
    if type(value) not in (int, float) or not math.isfinite(value):
        raise ValueError("expected finite numeric plot scalar")
    return struct.pack("<d", float(value))


def expected(case, index, replacement=None):
    calls = integer(case["count"])
    event = index - index % 5000
    ticks = replacement[1] if replacement is not None and event == replacement[0] else 400 + event
    return (calls * ticks + 2 * calls * (calls - 1)) / 4.0


def oracle(case, bars, replacement=None):
    fnv = FNV_OFFSET
    for index in range(bars):
        for byte in value_bits(expected(case, index, replacement)):
            fnv = ((fnv ^ byte) * FNV_MULTIPLIER) & U64
    return {"plotValues": bars, "naValues": 0, "allValuesMatchDirectOracle": True,
            "fnv1a64ValueBitsLe": f"{fnv:016x}"}


def require_equal(actual, wanted, description):
    if type(actual) is not type(wanted) or actual != wanted:
        raise ValueError(description)


def check_profile(profile, case, bars, fields):
    names = fields["fields"] if isinstance(fields, dict) else fields
    if len(names) != PROFILE_FIELD_COUNT or not isinstance(profile, dict) or sorted(profile) != sorted(names):
        raise ValueError("all 102 public profile fields must be present exactly")
    for key, value in profile.items():
        if key == "historyRetentionMode":
            if value not in {"staticTrimmed", "dynamicFull", "maxBarsBack"}:
                raise ValueError("unexpected retention mode")
        elif key == "historyHasDynamicOffsets":
            if type(value) is not bool:
                raise ValueError("history flag must be boolean")
        elif value is None and key in {"historyMaxBarsBack", "historyDynamicRetentionMaxMissedOffset"}:
            continue
        elif integer(value) < 0:
            raise ValueError("negative public profile counter")
    counters = {"bars": bars, "plots": 1, "plotValues": bars,
                "valuewhenStateSlots": case["count"], "valuewhenStateValues": case["count"] * bars,
                "strategyScriptPasses": 0, "strategyRecalculationPasses": 0}
    for key, wanted in counters.items():
        require_equal(profile[key], wanted, "independent profile counter differs: " + key)
    if profile["valuewhenStateValueCapacity"] < counters["valuewhenStateValues"]:
        raise ValueError("numeric persistent history physical capacity below logical count")


def profile_observations(metrics):
    """All 49 observations must match at corresponding before/after positions."""
    result = {key: metrics[key] for key in PROFILE_FIELDS}
    result.update({f"historicalClone[{row['sample']}]": row["profile"] for row in metrics["cloneChecks"]})
    for row in metrics["formingChecks"]:
        name = f"{row['method']}[{row['sample']}]"
        result[name + ".visible"] = row["profile"]
        result[name + ".confirmed"] = row["confirmedProfile"]
    if len(result) != 49:
        raise ValueError("unexpected complete profile observation count")
    return result


def validate(metrics, case, profileFields):
    if not isinstance(metrics, dict) or set(metrics) != TOP:
        raise ValueError("missing or unknown default-budget receipt field")
    calls, bars = case["count"], case["bars"]
    for key, wanted in {"probe": "publicDefaultValuewhenBudgetCompatibility", "callSites": calls,
                        "bars": bars, "pineSource": pine_source(calls), "samplesPerRepeatedStage": SAMPLES,
                        "configuredBudget": False, "allowedBeforeAfterProfileDifferences": [],
                        "profileFieldCount": PROFILE_FIELD_COUNT, "seededRevision": 1,
                        "publicRevision": 21, "confirmedReplacementQuarterTicks": 400 + bars + 3,
                        "logicalValues": {"seed": calls * bars, "preview": calls * (bars + 1),
                                          "confirmed": calls * (bars + 1), "final": calls * (bars + 2)}}.items():
        require_equal(metrics[key], wanted, "unexpected receipt fixture field: " + key)
    for key in ("oracle", "measurementScope", "allocatorScope", "limits", "limitations"):
        if not isinstance(metrics[key], str) or not metrics[key]:
            raise ValueError("missing scope or limitation: " + key)
    stages = metrics["stages"]
    if not isinstance(stages, dict) or set(stages) != SINGLE_STAGES | REPEATED_STAGES:
        raise ValueError("unexpected 8-stage layout")
    for name, observed in stages.items():
        samples = observed if name in REPEATED_STAGES else [observed]
        if type(samples) is not list or len(samples) != (SAMPLES if name in REPEATED_STAGES else 1):
            raise ValueError("missing original repeated-stage samples")
        for sample in samples:
            if not isinstance(sample, dict) or set(sample) != METRIC_FIELDS:
                raise ValueError("unexpected five-metric sample layout")
            if type(sample["ms"]) not in (int, float) or not math.isfinite(sample["ms"]) or sample["ms"] < 0:
                raise ValueError("invalid internal Instant time")
            for field in METRIC_FIELDS - {"ms"}:
                count = integer(sample[field])
                if field != "liveDeltaBytes" and count < 0:
                    raise ValueError("negative allocator request metric")
            if sample["peakAdditionalLiveBytes"] < max(0, sample["liveDeltaBytes"]):
                raise ValueError("phase additional peak below phase exit net live increase")
    replacement = (bars, 400 + bars + 3)
    proofs = {"seedOracle": oracle(case, bars), "confirmedOracle": oracle(case, bars + 1, replacement),
              "finalOracle": oracle(case, bars + 2, replacement)}
    for key, wanted in proofs.items():
        require_equal(metrics[key], wanted, "independent full-history hash differs: " + key)
        for field, value in wanted.items():
            require_equal(metrics[key][field], value, "incorrect oracle field type")
    for name, count in zip(PROFILE_FIELDS, (bars, bars, bars + 1, bars + 2)):
        check_profile(metrics[name], case, count, profileFields)
    clones = metrics["cloneChecks"]
    if type(clones) is not list or len(clones) != SAMPLES:
        raise ValueError("missing clone correctness observations")
    for index, observed in enumerate(clones):
        wanted = {"sample": index, "allValuesMatchDirectOracle": True,
                  "fnv1a64ValueBitsLe": proofs["seedOracle"]["fnv1a64ValueBitsLe"]}
        if not isinstance(observed, dict) or set(observed) != set(wanted) | {"profile"}:
            raise ValueError("unexpected clone correctness layout")
        for key, value in wanted.items():
            require_equal(observed[key], value, "clone oracle differs")
        check_profile(observed["profile"], case, bars, profileFields)
    checks = metrics["formingChecks"]
    if type(checks) is not list or len(checks) != 2 * SAMPLES:
        raise ValueError("missing all eighteen forming observations")
    for index, observed in enumerate(checks):
        sample = index % SAMPLES
        ticks = 400 + bars + (sample + 1 if index < SAMPLES else -(sample + 1))
        wanted = {"method": "update_without_output" if index < SAMPLES else "apply_update", "sample": sample,
                  "replacementQuarterTicks": ticks, "oracleBits": value_bits(expected(case, bars, (bars, ticks)))[::-1].hex(),
                  "previewEvents": calls * (bars + 1), "confirmedEvents": calls * bars, "revision": index + 2}
        if not isinstance(observed, dict) or set(observed) != set(wanted) | {"profile", "confirmedProfile"}:
            raise ValueError("unexpected forming correctness layout")
        for key, value in wanted.items():
            require_equal(observed[key], value, "independent forming value/event/revision oracle differs")
        check_profile(observed["profile"], case, bars + 1, profileFields)
        check_profile(observed["confirmedProfile"], case, bars, profileFields)
        require_equal(observed["confirmedProfile"], metrics["realtimeSeedProfile"], "forming touched confirmed profile")
    return {"oracles": proofs, "profiles": profile_observations(metrics),
            "profileObservations": 49, "profileFieldObservations": 49 * PROFILE_FIELD_COUNT,
            "allFormingOracleBitsAndRevisionsMatch": True, "allCloneHistoryHashesMatch": True,
            "logicalValues": metrics["logicalValues"], "defaultPreservesOverOneMillionAggregateEvents": calls * bars > 1_000_000}


def load_raw(path):
    if path.is_file():
        return path.read_bytes()
    compressed = path.with_suffix(path.suffix + ".gz")
    if compressed.is_file():
        return gzip.decompress(compressed.read_bytes())
    raise ValueError("raw payload missing: " + str(path))


def check_snapshot(document, case, bars, replacement):
    if not isinstance(document, dict) or type(document.get("plots")) is not list or len(document["plots"]) != 1:
        raise ValueError("expected one complete snapshot plot")
    plot = document["plots"][0]
    if not isinstance(plot, dict) or type(plot.get("values")) is not list or len(plot["values"]) != bars:
        raise ValueError("unexpected full snapshot history length")
    fnv = FNV_OFFSET
    for index, actual in enumerate(plot["values"]):
        raw = value_bits(actual)
        if raw != value_bits(expected(case, index, replacement)):
            raise ValueError("snapshot IEEE bits differ from independent integer-quarter formula")
        for byte in raw:
            fnv = ((fnv ^ byte) * FNV_MULTIPLIER) & U64
    return {"plotId": integer(plot["id"]), "plotValues": bars, "naValues": 0,
            "fnv1a64ValueBitsLe": f"{fnv:016x}", "allValuesMatchIndependentPythonOracle": True}


def validate_payloads(metrics, case, outdir):
    directory = Path(outdir).resolve()
    names = ["seed"] + [f"forming-apply-{index}" for index in range(SAMPLES)] + ["confirmed", "next-historical"]
    locators = metrics["rawPayloadFiles"]
    if type(locators) is not list or len(locators) != len(names) or len(set(locators)) != len(names):
        raise ValueError("expected twelve distinct raw public payloads")
    bars = case["bars"]
    result = {}
    plot_id = None
    # Without-output calls do not expose raw deltas. Independently derive their
    # ninth preview as the starting value state, then replay all nine actual
    # apply deltas. This qualifies value/revision replay, not full RuntimeReplica.
    replay = [expected(case, index, (bars, 400 + bars + SAMPLES)) for index in range(bars + 1)]
    revision = SAMPLES + 1
    for name, locator in zip(names, locators):
        if type(locator) is not str:
            raise ValueError("payload locator must be string")
        path = Path(locator).resolve()
        if not path.is_relative_to(directory) or not path.name.endswith("." + name + ".json"):
            raise ValueError("payload locator outside receipt directory or suffix differs")
        raw = load_raw(path)
        document = json.loads(raw)
        item = {"path": str(path), "sha256": hashlib.sha256(raw).hexdigest(), "bytes": len(raw)}
        if name in {"seed", "confirmed", "next-historical"}:
            count = bars + {"seed": 0, "confirmed": 1, "next-historical": 2}[name]
            replacement = None if name == "seed" else (bars, 400 + bars + 3)
            proof = check_snapshot(document, case, count, replacement)
            if plot_id is not None and proof["plotId"] != plot_id:
                raise ValueError("public plot identity changed")
            plot_id = proof["plotId"]
            item["pythonOracle"] = proof
        else:
            index = int(name.rsplit("-", 1)[1])
            wanted_revision = SAMPLES + index + 2
            for key, wanted in {"schemaVersion": 4, "revision": wanted_revision, "baseRevision": revision,
                                "retainedFrom": 0, "visibility": "preview"}.items():
                require_equal(document.get(key), wanted, "delta schema/revision/visibility differs")
            series = document.get("series")
            if type(series) is not list or len(series) != 1:
                raise ValueError("expected one real plot replacement delta")
            change = series[0]
            for key, wanted in {"family": "plot", "id": plot_id, "op": "replaceLast", "start": bars}.items():
                require_equal(change.get(key), wanted, "unexpected delta series operation")
            if change.get("colors") != [None] or type(change.get("values")) is not list or len(change["values"]) != 1:
                raise ValueError("unexpected numeric plot replacement payload")
            wanted = expected(case, bars, (bars, 400 + bars - index - 1))
            if value_bits(change["values"][0]) != value_bits(wanted):
                raise ValueError("actual delta value IEEE bits differ")
            replay[bars] = change["values"][0]
            for at, actual in enumerate(replay):
                if value_bits(actual) != value_bits(expected(case, at, (bars, 400 + bars - index - 1))):
                    raise ValueError("actual delta replay changed committed history or tail")
            for key in ("hlines", "fills", "drawings", "alerts", "diagnostics"):
                require_equal(document.get(key), [], "unexpected extra output family")
            revision = wanted_revision
            item["pythonOracle"] = {"revision": revision, "baseRevision": revision - 1,
                                    "visibility": "preview", "seriesValuesChecked": 1,
                                    "allDeltaValuesMatchIndependentOracle": True,
                                    "replayedPlotValues": bars + 1, "allReplayedPlotBitsMatchIndependentOracle": True}
        result[name] = item
    return result

build_report.py.content:
"""Write durable reports only from complete, audited, source-bound receipts.

Standard library only. Never import producers/auditors, spawn a process, build,
link, execute a probe or rerun a gate. Preparation of this file writes nothing
tracked. Running it requires all three final families and an independently
recorded actual audit exit. Profile interning is report storage normalization,
and expansion is checked against the original data before either report writes.
"""
from __future__ import annotations

from datetime import datetime, timezone
import gzip
import hashlib
import json
import math
from pathlib import Path
import re
import statistics
import traceback
import uuid

D = Path(__file__).resolve().parent
ROOT = D.parents[1]
REPORT_DATE = "2026-10-05"
MD_NAME = "ALERT_VALUEWHEN_BUDGET_REPAIR_20261005.md"
JSON_NAME = "ALERT_VALUEWHEN_BUDGET_REPAIR_RESULTS_20261005.json"
FAMILIES = ("alert-owned", "alert-borrowed", "budget")
COUNTS = {"alert-owned": 60, "alert-borrowed": 30, "budget": 36}
PAYLOAD_COUNTS = {"alert-owned": 34, "alert-borrowed": 34, "budget": 12}
