"""UTF-8/LF receipts and strict JSON primitives; importing starts no processes."""
from __future__ import annotations
from datetime import datetime, timezone
import gzip
import hashlib
import json
import math
from pathlib import Path
import subprocess
import time
import uuid

D = Path(__file__).resolve().parent
ROOT = D.parents[1]


def sha(path: Path) -> str:
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def save(path: Path, value: object) -> None:
    path = Path(path)
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_bytes((json.dumps(value, indent=2, ensure_ascii=False, allow_nan=False) + "\n").encode("utf8"))
    temporary.replace(path)


def _pairs(items):
    result = {}
    for key, value in items:
        if key in result:
            raise ValueError("Duplicate JSON field: " + key)
        result[key] = value
    return result


def _constant(token):
    raise ValueError("Nonfinite JSON token: " + token)


def _float(token):
    result = float(token)
    if not math.isfinite(result):
        raise ValueError("Out-of-f64-range JSON number: " + token)
    return result


def loads(raw):
    return json.loads(raw, object_pairs_hook=_pairs, parse_constant=_constant, parse_float=_float)


def read(path: Path):
    return loads(Path(path).read_text(encoding="utf-8-sig"))


def integer(value, minimum=None):
    if type(value) is not int or (minimum is not None and value < minimum):
        raise ValueError("Expected integer in the permitted range")
    return value


def number(value, signed=False):
    if (type(value) not in (int, float) or not math.isfinite(value)
            or (not signed and value < 0)):
        raise ValueError("Expected finite numeric measurement")
    return value


def source(path: Path, text: str) -> dict:
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    encoded = text.encode("utf8")
    if path.exists() and path.read_bytes() != encoded:
        raise ValueError("Prepared source differs: " + path.as_posix())
    if not path.exists():
        path.write_bytes(encoded)
    return {"path": path.as_posix(), "sha256": sha(path)}


def directory(prefix: str) -> Path:
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S.%fZ") + "-" + uuid.uuid4().hex[:8]
    result = D / (prefix + "-receipts") / stamp
    result.mkdir(parents=True, exist_ok=False)
    return result


def execute(out: Path, stem: str, command: list[str], timeout: float) -> tuple[dict, bytes]:
    started = time.monotonic()
    try:
        completed = subprocess.run(command, cwd=ROOT, capture_output=True, timeout=timeout)
        raw, errors, code = completed.stdout, completed.stderr, completed.returncode
    except subprocess.TimeoutExpired as error:
        raw, errors, code = error.stdout or b"", error.stderr or b"", None
    stdout, stderr, exit_path = (out / (stem + suffix) for suffix in (".stdout", ".stderr", ".exit.json"))
    stdout.write_bytes(raw)
    stderr.write_bytes(errors)
    save(exit_path, {"command":command, "returncode":code,
                     "timeoutSeconds":timeout if code is None else None})
    return {"command":command, "returncode":code, "wallSeconds":time.monotonic()-started,
            "stdout":stdout.as_posix(), "stderr":stderr.as_posix(), "exit":exit_path.as_posix(),
            "stdoutSha256":sha(stdout), "stderrSha256":sha(stderr), "exitSha256":sha(exit_path)}, raw


def exact_payload(path: Path, out: Path) -> bytes:
    path = Path(path).resolve()
    if not path.is_relative_to(out.resolve()) or path.parent != out.resolve() or path.suffix != ".json":
        raise ValueError("Raw payload is outside this exact receipt directory")
    if not path.is_file() or path.is_symlink():
        raise ValueError("Raw payload is missing or is a link")
    return path.read_bytes()


def compress_payload(row: dict, out: Path) -> dict:
    """Roundtrip each validated exact file; delete only that file after verification."""
    path = Path(row["path"]).resolve()
    raw = exact_payload(path, out)
    original_sha = hashlib.sha256(raw).hexdigest()
    if row.get("originalSha256") != original_sha or row.get("originalBytes") != len(raw):
        raise ValueError("Validated payload changed before gzip")
    compressed_path = path.with_suffix(path.suffix + ".gz")
    with compressed_path.open("xb") as output:
        output.write(gzip.compress(raw, mtime=0))
    compressed = compressed_path.read_bytes()
    if gzip.decompress(compressed) != raw or path.read_bytes() != raw:
        raise ValueError("Gzip roundtrip or original-file identity differs")
    # Both resolved targets were checked in this run's unique directory above.
    path.unlink()
    return {**row, "originalPath":path.as_posix(), "path":compressed_path.as_posix(),
            "gzipSha256":hashlib.sha256(compressed).hexdigest(), "gzipBytes":len(compressed),
            "compression":"gzip", "mtime":0, "originalRemovedAfterVerifiedRoundtrip":True}


def decode_payload(row: dict) -> bytes:
    compressed = Path(row["path"]).read_bytes()
    if len(compressed) != row["gzipBytes"] or hashlib.sha256(compressed).hexdigest() != row["gzipSha256"]:
        raise ValueError("Compressed payload identity differs")
    raw = gzip.decompress(compressed)
    if len(raw) != row["originalBytes"] or hashlib.sha256(raw).hexdigest() != row["originalSha256"]:
        raise ValueError("Decoded original payload identity differs")
    return raw

independent_audit.py.content:
"""Read existing frozen receipts and actual outputs; never build or run probes.

The fixture checkers are reused only for arithmetic/schema checks over actual
decoded payloads. No producer success boolean or stored median is proof. This
module never imports the process runner and never launches a subprocess.
"""
from __future__ import annotations

from datetime import datetime, timezone
import gzip
import hashlib
import json
import math
from pathlib import Path
import re
import statistics
import struct
import sys
import tarfile
import traceback
import uuid

D = Path(__file__).resolve().parent
ROOT = D.parents[1]
METRICS = ("allocatedBytes", "allocations", "liveDeltaBytes", "ms", "peakAdditionalLiveBytes")
SAMPLES = 9
REPETITIONS = 3
FAMILIES = {
    "alert-owned": {"probe": "alert", "processes": 60, "payloads": 34,
                    "tags": ("before", "after"), "mode": "owned"},
    "alert-borrowed": {"probe": "alert_ref", "processes": 30, "payloads": 34,
                       "tags": ("after",), "mode": "borrowed"},
    "budget": {"probe": "budget", "processes": 36, "payloads": 12,
               "tags": ("before", "after"), "mode": "owned"},
}
ALERT_SINGLE = {"analyze", "seedWithoutOutput", "confirmed", "nextHistorical", "nextFormingAfterConfirmation"}
ALERT_REPEATED = {"formingWithoutOutput", "formingApply", "returnedChangesClone"}
BUDGET_SINGLE = {"analyze", "historicalSeed", "realtimeSeedWithoutOutput", "confirmedWithoutOutput", "nextHistoricalWithoutOutput"}
BUDGET_REPEATED = {"historicalClone", "formingWithoutOutput", "formingApplyUpdate"}
DIRECT_LIBRARIES = {"libpine_runtime.rlib", "libpine_sema.rlib", "libpine_syntax.rlib", "libserde_json-ff9aee5763d82a17.rlib"}


def require(condition, message):
    if not condition:
        raise ValueError(message)


def integer(value, minimum=None):
    require(type(value) is int and (minimum is None or value >= minimum), "Expected exact integer")
    return value


def pairs(items):
    result = {}
    for key, value in items:
        require(key not in result, "Duplicate JSON field: " + key)
        result[key] = value
    return result


def finite_float(token):
    value = float(token)
    require(math.isfinite(value), "JSON f64 number outside finite range")
    return value


def reject_constant(token):
    raise ValueError("Nonfinite JSON token: " + token)


def loads(raw):
    return json.loads(raw, object_pairs_hook=pairs, parse_constant=reject_constant, parse_float=finite_float)


def read(path):
    return loads(Path(path).read_text(encoding="utf-8-sig"))


def digest(raw):
    return hashlib.sha256(raw).hexdigest()


def sha(path):
    with Path(path).open("rb") as source:
        result = hashlib.sha256()
        for block in iter(lambda: source.read(1 << 20), b""):
            result.update(block)
    return result.hexdigest()


def save(path, value):
    temporary = Path(path).with_suffix(Path(path).suffix + ".tmp")
    temporary.write_bytes((json.dumps(value, indent=2, ensure_ascii=False, allow_nan=False) + "\n").encode("utf8"))
    temporary.replace(path)


def resolve(path):
    value = Path(path)
    return value.resolve() if value.is_absolute() else (ROOT / value).resolve()


def exact_file(path, expected, parent=None):
    path = resolve(path)
    require(path.is_file() and not path.is_symlink(), "Missing/nonregular file: " + str(path))
    if parent is not None:
        require(path.parent == Path(parent).resolve(), "File escaped its exact receipt directory")
    require(sha(path) == expected, "File SHA differs: " + str(path))
    return path


def verify_tar(path, files):
    found = {}
    with tarfile.open(path, "r") as archive:
        for member in archive:
            require(member.isfile() and member.name not in found, "Source archive has a nonregular/duplicate member")
            require(member.name in files, "Source archive has an unbound file")
            with archive.extractfile(member) as stream:
                result = hashlib.sha256()
                for block in iter(lambda: stream.read(1 << 20), b""):
                    result.update(block)
            found[member.name] = result.hexdigest()
    require(found == files, "Source archive bytes/file set differ from manifest")
    return {"path": str(path), "sha256": sha(path), "files": len(found)}


def source_binding():
    manifest_path = D / "source-identity.json"
    manifest = read(manifest_path)
    for path, expected in manifest["files"].items():
        exact_file(path, expected)
    return {"manifestSha256": sha(manifest_path), "archiveSha256": sha(D / "source.tar"),
            "files": len(manifest["files"]), "sourceVerified": True}


def verify_baseline():
    proof = read(D / "before-binary-identity.json")
    manifest = read(D / "before-source-identity.json")
    require(proof["beforeManifestSha256"] == sha(D / "before-source-identity.json"), "Baseline manifest identity differs")
    require(proof["beforeArchiveSha256"] == sha(D / "before-source.tar"), "Baseline archive identity differs")
    require(proof["beforeSourceFiles"] == len(manifest["files"]), "Baseline file count differs")
    require(len(proof["libraries"]) == 311 and proof["compilerArtifacts"] == 311, "Expected all 311 sealed compiler artifacts")
    for row in proof["libraries"].values():
        path = exact_file(row["archive"], row["sha256"])
        require(path.is_relative_to((D / "baseline").resolve()) and path.stat().st_size == row["bytes"], "Baseline artifact path/bytes differ")
    for row in proof["tools"].values():
        exact_file(row["executable"], row["executableSha256"])
    prior_path = exact_file(proof["compiledPriorManifest"], proof["compiledPriorManifestSha256"])
    prior = read(prior_path)
    require(len(prior["files"]) == proof["compiledPriorFiles"], "Prior compiled source count differs")
    require(all(manifest["files"].get(path) == expected for path, expected in prior["files"].items()), "Prior compiled source is not an unchanged baseline subset")
    require(sorted(set(manifest["files"]) - set(prior["files"])) == sorted(proof["addedNoncompiledReportFiles"]), "Unexpected source additions between prior build and baseline")
    prior_link = read(exact_file(proof["priorLinkReceipt"], proof["priorLinkReceiptSha256"]))
    require(prior_link["sourceManifestSha256"] == proof["compiledPriorManifestSha256"], "Prior linked library source proof differs")
    require(prior_link["libraryHashes"] == proof["directPriorLinkedLibraries"], "Prior four linked library proof differs")
    for original, expected in proof["directPriorLinkedLibraries"].items():
        require(proof["libraries"][original]["sha256"] == expected, "Sealed library differs from source-bound prior link")
    archive = verify_tar(D / "before-source.tar", manifest["files"])
    return proof, {"identitySha256": sha(D / "before-binary-identity.json"), "sourceArchiveSha256": archive["sha256"],
                   "compilerArtifacts": 311, "sourceFiles": len(manifest["files"]), "baseCommit": proof["baseCommit"]}


def verify_phase(name, binding):
    path = D / ("phase-" + name + ".json")
    phase = read(path)
    require(phase["phase"] == name and phase["status"] == "passed" and integer(phase["returncode"]) == 0, "Phase did not actually pass: " + name)
    require(phase["before"] == binding and phase["after"] == binding, "Phase source changed/differs: " + name)
    exact_file(D / "run_phase.py", phase["wrapperSha256"])
    exact_file(D / ("phase-" + name + "-wrapper.log"), phase["wrapperLogSha256"])
    if name.startswith("gate-"):
        artifacts = {"gateLogSha256": D / (name + ".log"), "gateExitSha256": D / (name + ".exit")}
        exit_path = D / (name + ".exit")
    elif name == "release":
        artifacts = {"buildLogSha256": D / "build-release.log", "buildExitSha256": D / "build-release.exit"}
        exit_path = D / "build-release.exit"
    else:
        _, probe, tag = name.split("-")
        artifacts = {"linkReceiptSha256": D / f"identity-{probe}-{tag}.json", "linkLogSha256": D / f"link-{probe}-{tag}.log"}
        exit_path = D / f"link-{probe}-{tag}.exit"
    require(exit_path.read_text(encoding="utf-8-sig").strip() == "0", "Actual phase exit file is nonzero")
    for key, artifact in artifacts.items():
        exact_file(artifact, phase[key])
    return {"path": path.as_posix(), "sha256": sha(path), "artifactHashes": {key: sha(value) for key, value in artifacts.items()}}


def verify_identity(probe, tag, plan, baseline):
    path = D / f"identity-{probe}-{tag}.json"
    identity = read(path)
    require(identity["probe"] == probe and identity["tag"] == tag, "Wrong probe/link version")
    executable = exact_file(D / f"{probe}-{tag}.exe", identity["executableSha256"])
    exact_file(plan["probeSource"]["path"], identity["sourceSha256"])
    require(identity["sourceSha256"] == plan["probeSource"]["sha256"], "Link entry differs from plan")
    manifest_path = D / ("before-source-identity.json" if tag == "before" else "source-identity.json")
    require(identity["sourceManifestSha256"] == sha(manifest_path), "Link source manifest differs")
    require(len(identity["additionalSourceHashes"]) == 1, "Exactly one include must be linked")
    for include, expected in identity["additionalSourceHashes"].items():
        require(resolve(include) == resolve(plan["includeSource"]["path"]) and expected == plan["includeSource"]["sha256"], "Link includes differ from plan")
        exact_file(include, expected)
    require(len(identity["libraryHashes"]) == 4 and {Path(path).name for path in identity["libraryHashes"]} == DIRECT_LIBRARIES, "Exact four linked libraries required")
    for library, expected in identity["libraryHashes"].items():
        linked = exact_file(library, expected)
        if tag == "before":
            matches = [row for row in baseline["libraries"].values() if resolve(row["archive"]) == linked and row["sha256"] == expected]
            require(linked.is_relative_to((D / "baseline").resolve()) and len(matches) == 1, "Before link is not sealed/proven")
    require(identity["rustc"] == baseline["tools"]["rustc"]["verboseVersion"].splitlines()[0], "Compiler version differs")
    normalized = [item.replace(".local/alert-budget-20261005/baseline", "LIBROOT").replace("target/release", "LIBROOT") for item in identity["compilerArguments"]]
    wanted = ["--edition=2024", "-O", "-C", "lto=thin", "-C", "codegen-units=1", "-L", "dependency=LIBROOT/deps",
              "--extern", "pine_runtime=LIBROOT/libpine_runtime.rlib", "--extern", "pine_sema=LIBROOT/libpine_sema.rlib",
              "--extern", "pine_syntax=LIBROOT/libpine_syntax.rlib", "--extern", "serde_json=LIBROOT/deps/libserde_json-ff9aee5763d82a17.rlib"]
    if probe == "alert_ref":
        wanted += ["--cfg", "borrowed_delta"]
    require(normalized == wanted, "Optimizing compiler arguments differ")
    exit_path = D / f"link-{probe}-{tag}.exit"
    require(exit_path.read_text(encoding="utf-8-sig").strip() == "0", "Actual link exit is nonzero")
    return {"binary": executable.as_posix(), "binarySha256": sha(executable), "probeSource": plan["probeSource"],
            "includeSource": plan["includeSource"], "sourceManifestSha256": sha(manifest_path),
            "linkReceipt": path.as_posix(), "linkReceiptSha256": sha(path), "linkLogSha256": sha(D / f"link-{probe}-{tag}.log"),
            "linkExitSha256": sha(exit_path), "normalizedCompilerArguments": normalized, "link": identity}


def profile_schema():
    path = ROOT / "crates/pine-runtime/src/output/json/profile.rs"
    fields = re.findall(r'\\"([A-Za-z][A-Za-z0-9]*)\\":', path.read_text(encoding="utf8"))
    require(len(fields) == 102 and len(set(fields)) == 102, "Expected complete 102-field public profile schema")
    return {"path": path.as_posix(), "sha256": sha(path), "fields": sorted(fields)}


def profile_observations(metrics, family, fields):
    if family.startswith("alert-"):
        names = ("seedProfile", "confirmedProfile", "historicalProfile", "finalPreviewProfile", "finalConfirmedProfile")
        result = {name: metrics[name] for name in names}
        for at, row in enumerate(metrics["formingChecks"]):
            result[f"forming[{at}].preview"] = row["previewProfile"]
            result[f"forming[{at}].confirmed"] = row["confirmedProfile"]
        require(len(result) == 41, "Alert profile observation count differs")
    else:
        names = ("seedProfile", "realtimeSeedProfile", "confirmedProfile", "finalProfile")
        result = {name: metrics[name] for name in names}
        for at, row in enumerate(metrics["cloneChecks"]):
            result[f"clone[{at}]"] = row["profile"]
        for at, row in enumerate(metrics["formingChecks"]):
            result[f"forming[{at}].preview"] = row["profile"]
            result[f"forming[{at}].confirmed"] = row["confirmedProfile"]
        require(len(result) == 49, "Budget profile observation count differs")
    for profile in result.values():
        require(type(profile) is dict and sorted(profile) == fields, "Profile field set is incomplete")
        for key, value in profile.items():
            if key == "historyRetentionMode":
                require(value in {"staticTrimmed", "dynamicFull", "maxBarsBack"}, "Invalid history retention mode")
            elif key == "historyHasDynamicOffsets":
                require(type(value) is bool, "History flag is not bool")
            elif value is None and key in {"historyMaxBarsBack", "historyDynamicRetentionMaxMissedOffset"}:
                pass
            else:
                integer(value, 0)
    return result


def raw_medians(metrics, family):
    single, repeated = (ALERT_SINGLE, ALERT_REPEATED) if family.startswith("alert-") else (BUDGET_SINGLE, BUDGET_REPEATED)
    stages = metrics["stages"]
    require(type(stages) is dict and set(stages) == single | repeated, "Named public stages differ")
    medians, observations = {}, 0
    for name, value in stages.items():
        rows = value if name in repeated else [value]
        require(type(rows) is list and len(rows) == (9 if name in repeated else 1), "Original sample count differs")
        for row in rows:
            require(type(row) is dict and set(row) == set(METRICS), "Original five metric fields differ")
            require(type(row["ms"]) in (int, float) and math.isfinite(row["ms"]) and row["ms"] >= 0, "Invalid Instant time")
            for field in set(METRICS) - {"ms"}:
                integer(row[field], None if field == "liveDeltaBytes" else 0)
            require(row["peakAdditionalLiveBytes"] >= max(0, row["liveDeltaBytes"]), "Additional peak is below positive net live change")
            observations += 1
        medians[name] = {field: statistics.median(row[field] for row in rows) for field in METRICS}
    require(observations == 32, "Expected 32 raw stage measurements per process")
    return medians, observations


def decoded_payload(row, outdir):
    path = exact_file(row["path"], row["gzipSha256"], outdir)
    require(path.name.endswith(".json.gz") and row["compression"] == "gzip" and integer(row["mtime"]) == 0, "Unexpected payload compression format")
    compressed = path.read_bytes()
    require(len(compressed) == integer(row["gzipBytes"], 0) and len(compressed) >= 10 and int.from_bytes(compressed[4:8], "little") == 0, "Gzip byte length/mtime differs")
    original = resolve(row["originalPath"])
    require(original.parent == Path(outdir).resolve() and str(path) == str(original) + ".gz", "Compressed/original locator differs")
    require(not original.exists() and row["originalRemovedAfterVerifiedRoundtrip"] is True, "Expected preserved gzip and exact removed original locator")
    raw = gzip.decompress(compressed)
    require(len(raw) == integer(row["originalBytes"], 0) and digest(raw) == row["originalSha256"], "Decoded payload original SHA/bytes differ")
    return raw


def exact_public_versions(value, full):
    require(type(value["schemaVersion"]) is int and value["schemaVersion"] == (9 if full else 4), "Exact public schema version differs")
    if full:
        require(type(value["renderMetadataVersion"]) is int and value["renderMetadataVersion"] == 1, "Exact render metadata version differs")


def budget_plot_id_from_source(text, case):
    # This exact v6 fixture contains only direct builtin calls with scalar
    # arguments: no UDF, nested call, method or legacy conversion. lower_program
    # keeps its indicator declaration expression; generic builtin lowering
    # allocates a CallSiteId for that call as well as every ta/plot call.
    calls = re.findall(r"(?<![\w.])([A-Za-z_]\w*(?:\.[A-Za-z_]\w*)*)\s*\(", text)
    expected = ["indicator"] + ["ta.valuewhen"] * case["count"] + ["plot"]
    require(calls == expected, "Budget source has unexpected direct call order")
    return calls.index("plot")


def verify_payloads(metrics, row, family, outdir, metric_path, alert, budget):
    locators = metrics["rawPayloadFiles"]
    payloads = row["payloads"]
    require(len(payloads) == FAMILIES[family]["payloads"] and len({entry["role"] for entry in payloads}) == len(payloads), "Payload count/roles differ")
    expected_roles = alert.payload_roles() if family.startswith("alert-") else ["seed"] + [f"forming-apply-{at}" for at in range(9)] + ["confirmed", "next-historical"]
    require([entry["role"] for entry in payloads] == expected_roles, "Complete ordered payload roles differ")
    for at, entry in enumerate(payloads):
        role = entry["role"]
        original = metric_path.with_suffix("." + role + ".json")
        require(resolve(entry["originalPath"]) == original.resolve(), "Payload does not belong to exact process receipt/role")
        locator = locators[at]["path"] if family.startswith("alert-") else locators[at]
        require(resolve(locator) == original.resolve(), "Actual stdout payload locator differs")
        raw = decoded_payload(entry, outdir)
        value = loads(raw)
        full = role.endswith("-full") if family.startswith("alert-") else role in {"seed", "confirmed", "next-historical"}
        exact_public_versions(value, full)
        if family.startswith("alert-"):
            # The checker below independently validates every full event/message
            # and every plot value and real delta, from the decoded gzip files.
            continue
        case = row["case"]
        plot_id = budget_plot_id_from_source(metrics["pineSource"], case)
        if full:
            count = case["bars"] + {"seed": 0, "confirmed": 1, "next-historical": 2}[role]
            replacement = None if role == "seed" else (case["bars"], 400 + case["bars"] + 3)
            require(set(value) == alert.FULL_KEYS, "Budget full snapshot schema has unexpected/missing output families")
            require(all(value[name] == [] for name in alert.FULL_ARRAYS) and value["alerts"] == [], "Budget snapshot has unexpected nonfixture output")
            require(len(value["plots"]) == 1 and set(value["plots"][0]) == {"id", "values"}, "Budget plot default/header omission differs")
            require(integer(value["plots"][0]["id"]) == plot_id, "Budget plot ID differs from source call order")
            require(len(value["plots"][0]["values"]) == count, "Budget full history length differs")
            for index, actual in enumerate(value["plots"][0]["values"]):
                require(budget.value_bits(actual) == budget.value_bits(budget.expected(case, index, replacement)), "Budget snapshot bits differ from independent quarter arithmetic")
        else:
            require(set(value) == alert.DELTA_KEYS, "Budget delta schema has unknown/missing fields")
            require(all(value[name] == [] for name in ("hlines", "fills", "drawings", "alerts", "diagnostics")), "Budget delta has unexpected nonfixture output")
            require(len(value["series"]) == 1 and set(value["series"][0]) == {"family", "id", "op", "start", "values", "colors"}, "Budget exact changed plot fields differ")
            require(integer(value["series"][0]["id"]) == plot_id, "Budget delta ID differs from source call order")
    if family.startswith("alert-"):
        proof = alert.validate_payloads(metrics, row["case"], outdir, receipt=metric_path)
        wanted = [{"role": item["role"], "originalSha256": item["originalSha256"], "originalBytes": item["originalBytes"]} for item in payloads]
        actual = [{key: item[key] for key in ("role", "originalSha256", "originalBytes")} for item in proof]
        require(actual == wanted, "Independently checked alert payload identity differs")
    else:
        proof = budget.validate_payloads(metrics, row["case"], outdir)
        require(list(proof) == expected_roles, "Independently checked budget roles differ")
        for item in payloads:
            require(proof[item["role"]]["sha256"] == item["originalSha256"] and proof[item["role"]]["bytes"] == item["originalBytes"], "Independently checked budget payload identity differs")
    return len(payloads)


def version_medians(rows, cases):
    result = []
    for case in cases:
        selected = [row for row in rows if row["case"]["name"] == case["name"]]
        versions = {}
        for tag in dict.fromkeys(row["tag"] for row in selected):
            actual = [row for row in selected if row["tag"] == tag]
            require(len(actual) == 3 and sorted(row["repetition"] for row in actual) == [0, 1, 2], "Fresh-process outer median group differs")
            versions[tag] = {stage: {field: statistics.median(row["recomputedMedians"][stage][field] for row in actual) for field in METRICS} for stage in actual[0]["recomputedMedians"]}
        result.append({"case": case["name"], "versionMedians": versions})
    return result


def comparisons(left, right, left_tag, right_tag):
    result = []
    require(len(left) == len(right), "Compared median case count differs")
    for old, new in zip(left, right):
        require(old["case"] == new["case"], "Compared median case order differs")
        a, b = old["versionMedians"][left_tag], new["versionMedians"][right_tag]
        for stage in a:
            for metric in METRICS:
                before, after = a[stage][metric], b[stage][metric]
                result.append({"case": old["case"], "stage": stage, "metric": metric, "left": before, "right": after,
                               "delta": after - before, "ratio": after / before if before != 0 else None,
                               "percentChange": (after - before) / abs(before) * 100 if before != 0 else None,
                               "timeIncreaseOverFivePercent": metric == "ms" and before > 0 and after > before * 1.05,
                               "allocationCountOrPeakIncrease": metric in {"allocatedBytes", "allocations", "peakAdditionalLiveBytes"} and after > before,
                               "signedNetLiveDeltaChanged": metric == "liveDeltaBytes" and after != before})
    return result


def pair_outputs(left, right):
    require(left["profiles"] == right["profiles"], "All 102 profile fields differ across corresponding observations")
    require(len(left["row"]["payloads"]) == len(right["row"]["payloads"]), "Paired payload count differs")
    for old, new in zip(left["row"]["payloads"], right["row"]["payloads"]):
        require(old["role"] == new["role"], "Paired payload roles differ")
        require(decoded_payload(old, left["outdir"]) == decoded_payload(new, right["outdir"]), "Actual decoded full public JSON bytes differ")
    return len(left["profiles"]), len(left["row"]["payloads"])


def audit(outdir):
    import alert_validation as alert
    import budget_validation as budget

    # Exact schema versions/call-allocation facts above come from these frozen
    # core sources; do not silently accept a later semantic ABI change.
    model = (ROOT / "crates/pine-runtime/src/output/model.rs").read_text()
    changes = (ROOT / "crates/pine-runtime/src/output/changes.rs").read_text()
    analyzer = (ROOT / "crates/pine-sema/src/analysis.rs").read_text()
    require("PUBLIC_RUNTIME_SCHEMA_VERSION: u32 = 9;" in model and "PUBLIC_RENDER_METADATA_VERSION: u32 = 1;" in model, "Public snapshot constants differ")
    require("PUBLIC_RUNTIME_CHANGES_SCHEMA_VERSION: u32 = 4;" in changes and "next_call_site_id: 0," in analyzer, "Delta/call-allocation constants differ")
    binding = source_binding()
    baseline, baseline_summary = verify_baseline()
    source = read(D / "source-identity.json")
    require(source["base_commit"] == baseline_summary["baseCommit"], "Source and baseline commit identities differ")
    allocation_paths = ("crates/pine-sema/src/analysis.rs", "crates/pine-sema/src/analyzer/context.rs",
                        "crates/pine-sema/src/lowering/program.rs", "crates/pine-sema/src/lowering/mod.rs")
    before_source = read(D / "before-source-identity.json")
    allocation_sources = {}
    for path in allocation_paths:
        require(before_source["files"][path] == source["files"][path], "Before/after call-allocation source changed")
        exact_file(path, source["files"][path])
        allocation_sources[path] = source["files"][path]
    final_archive = verify_tar(D / "source.tar", source["files"])
    schema = profile_schema()
    phases = {name: verify_phase(name, binding) for name in ("gate-windows", "gate-linux", "release", "link-alert-after", "link-alert_ref-after", "link-budget-after")}
    reports, cached = {}, {}
    totals = {"processes": 0, "payloads": 0, "rawStageMeasurements": 0, "rawMetricValues": 0,
              "profileObservations": 0, "profileFieldObservations": 0, "pairedProfileObservations": 0,
              "pairedProfileFieldComparisons": 0, "pairedFullPayloadByteEqualities": 0}
    for family, spec in FAMILIES.items():
        result_path = D / (family + "-results.json")
        result = read(result_path)
        require(result["family"] == family and result["status"] == "passed", "Expected complete passing family")
        require(integer(result["qualifiedProcesses"]) == spec["processes"] and integer(result["attemptedProcesses"]) == spec["processes"], "Family actual/qualified process count differs")
        plan_path = D / (family + "-plan.json")
        plan = read(plan_path)
        require(result["plan"] == plan and result["planSha256"] == sha(plan_path), "Prepared plan differs from executed batch")
        require(plan["family"] == family and plan["plannedProcesses"] == spec["processes"] and plan["probesExecuted"] is False, "Preparation-only matrix identity differs")
        require(plan["repetitionsPerVersion"] == 3 and plan["samplesPerRepeatedStage"] == 9 and plan["stageMeasurementsPerProcess"] == 32 and plan["rawPayloadsPerProcess"] == spec["payloads"], "Fixed sampling layout differs")
        require(plan["profileSchema"] == schema and plan["metricFields"] == list(METRICS) and plan["tags"] == list(spec["tags"]), "Complete profile/metric/version schema differs")
        single, repeated = (ALERT_SINGLE, ALERT_REPEATED) if family.startswith("alert-") else (BUDGET_SINGLE, BUDGET_REPEATED)
        require(plan["singleStages"] == sorted(single) and plan["repeatedStages"] == sorted(repeated), "Prepared stage names differ from independent contract")
        checker_file = "alert_validation.py" if family.startswith("alert-") else "budget_validation.py"
        include_file = "alert_probe_common.rs" if family.startswith("alert-") else "budget_probe_common.rs"
        expected_helpers = {spec["probe"] + "_probe.rs", include_file, "performance_runner.py", "evidence_common.py", checker_file}
        require(len(plan["sourceFiles"]) == 5 and {Path(item["path"]).name for item in plan["sourceFiles"]} == expected_helpers, "Exactly the five probe/include/runner/helper/checker files must be archived")
        checker = alert if family.startswith("alert-") else budget
        wanted_cases = checker.cases()
        require(len(plan["cases"]) == len(wanted_cases), "Independent fixture count differs")
        for actual, wanted in zip(plan["cases"], wanted_cases):
            require(all(actual[key] == value for key, value in wanted.items()), "Independent fixture order/arguments differ")
            text = checker.pine_source(actual) if family.startswith("alert-") else checker.pine_source(actual["count"])
            require(actual["pineSource"] == text and resolve(actual["source"]["path"]).read_bytes() == text.encode("utf8"), "Input Pine bytes differ from independent fixture")
            exact_file(actual["source"]["path"], actual["source"]["sha256"])
        identities = {tag: verify_identity(spec["probe"], tag, plan, baseline) for tag in spec["tags"]}
        receipt_directory = resolve(result["receiptDirectory"])
        require(receipt_directory.parent == (D / (family + "-receipts")).resolve(), "Family receipt directory escaped scope")
        require(read(receipt_directory / "plan.json") == plan and read(receipt_directory / "batch.json") == result, "Durable batch/plan differ from result")
        for helper in plan["sourceFiles"]:
            exact_file(helper["path"], helper["sha256"])
            exact_file(receipt_directory / Path(helper["path"]).name, helper["sha256"])
        pre = result["prerequisites"]
        require(pre == result["finalPrerequisites"] and pre["sourceBinding"] == binding, "Before/after family prerequisite identity differs")
        require(pre["identities"] == identities, "Executable/link identities differ from family prerequisite")
        for name, phase in pre["phases"].items():
            require(phase == phases[name], "Family gate/release/link hash differs")
        require(pre["baselineArchive"] == {key: baseline_summary[key] for key in ("identitySha256", "sourceArchiveSha256", "compilerArtifacts")}, "Sealed baseline prerequisite differs")
        schedule = []
        for case in plan["cases"]:
            for repetition in range(3):
                tags = ("after",) if family == "alert-borrowed" else (("before", "after") if repetition % 2 == 0 else ("after", "before"))
                schedule.extend((case, repetition, tag) for tag in tags)
        require(len(result["processes"]) == len(schedule) == spec["processes"], "Actual fresh-process schedule is incomplete")
        checked = []
        for at, (row, scheduled) in enumerate(zip(result["processes"], schedule)):
            case, repetition, tag = scheduled
            require(row["case"] == case and row["repetition"] == repetition and row["tag"] == tag, "Alternating before/after fresh-process schedule differs")
            require(row["binaryIdentity"] == identities[tag] and row["phaseSourceBinding"] == binding and row["inputSourceSha256"] == case["source"]["sha256"], "Individual process source/binary/input binding differs")
            require(row["individuallyValidated"] is True, "Qualified batch contains an incomplete producer row")
            metric_path = resolve(row["metricReceipt"]["path"])
            expected_path = receipt_directory / f'{case["name"]}-{tag}-{repetition}.metrics.json'
            require(metric_path == expected_path.resolve(), "Metric receipt path differs from process schedule")
            process = row["process"]
            require(integer(process["returncode"]) == 0, "Stored actual process exit was nonzero")
            stdout = exact_file(process["stdout"], process["stdoutSha256"], receipt_directory).read_bytes()
            stderr = exact_file(process["stderr"], process["stderrSha256"], receipt_directory).read_bytes()
            exit_value = read(exact_file(process["exit"], process["exitSha256"], receipt_directory))
            argument = case["prefixChars"] if family.startswith("alert-") else case["bars"]
            command = [identities[tag]["binary"], str(case["count"]), str(argument), metric_path.as_posix()]
            require(process["command"] == command and exit_value["command"] == command and integer(exit_value["returncode"]) == 0 and exit_value["timeoutSeconds"] is None, "Actual process command/exit/timeout differs")
            require(stderr == b"", "Probe emitted unexpected stderr")
            lines = stdout.splitlines()
            require(len(lines) == 1 and lines[0] and exact_file(metric_path, row["metricReceipt"]["sha256"], receipt_directory).read_bytes() == lines[0], "Original stdout does not exactly match metric receipt")
            metrics = loads(lines[0])
            require(metrics == row["metrics"], "Stored metrics differ from actual stdout")
            # Checkers are arithmetic guards, not success attestations. Raw
            # payloads are decoded/hash checked/revalidated immediately below.
            if family.startswith("alert-"):
                checker.validate(metrics, case, schema["fields"], mode=spec["mode"])
            else:
                checker.validate(metrics, case, schema["fields"])
            medians, raw_count = raw_medians(metrics, family)
            require(medians == row["processMedians"], "Stored process median differs from original raw samples")
            profiles = profile_observations(metrics, family, schema["fields"])
            payload_count = verify_payloads(metrics, row, family, receipt_directory, metric_path, alert, budget)
            original_rows = row["uncompressedPayloadIdentity"]
            require(len(original_rows) == payload_count, "Original validated payload identities are incomplete")
            for original, compressed in zip(original_rows, row["payloads"]):
                require(original["role"] == compressed["role"] and resolve(original["path"]) == resolve(compressed["originalPath"])
                        and original["originalSha256"] == compressed["originalSha256"] and original["originalBytes"] == compressed["originalBytes"],
                        "Validated raw identity differs from compressed original identity")
            item = {"row": row, "outdir": receipt_directory, "profiles": profiles, "metrics": metrics, "recomputedMedians": medians,
                    "case": case, "tag": tag, "repetition": repetition}
            checked.append(item)
            cached[(family, case["name"], tag, repetition)] = item
            totals["processes"] += 1
            totals["payloads"] += payload_count
            totals["rawStageMeasurements"] += raw_count
            totals["rawMetricValues"] += raw_count * 5
            totals["profileObservations"] += len(profiles)
            totals["profileFieldObservations"] += len(profiles) * 102
            save(outdir / "progress.json", {"family": family, "familyProcess": at + 1, **totals})
            if (at + 1) % 10 == 0 or at + 1 == len(schedule):
                print(f"{family}: audited {at + 1}/{len(schedule)} existing processes; payloads {totals['payloads']}", flush=True)
        medians = version_medians(checked, plan["cases"])
        require(medians == result["medians"], "Stored version median differs from three fresh process medians")
        if family == "alert-borrowed":
            costs = comparisons(reports["alert-owned"]["medians"], medians, "after", "after")
        else:
            costs = comparisons(medians, medians, "before", "after")
        require(costs == result["comparisons"], "Stored comparison/delta/ratio differs from recomputed medians")
        for key, flag in (("timeIncreasesOverFivePercent", "timeIncreaseOverFivePercent"), ("allocationCountOrPeakIncreases", "allocationCountOrPeakIncrease"), ("signedNetLiveDeltaChanges", "signedNetLiveDeltaChanged")):
            require(result[key] == [value for value in costs if value[flag]], "Stored tradeoff list omits/changes a measured observation")
        for case in plan["cases"]:
            for repetition in range(3):
                right = cached[(family, case["name"], "after", repetition)]
                left = cached[("alert-owned", case["name"], "after", repetition)] if family == "alert-borrowed" else cached[(family, case["name"], "before", repetition)]
                profile_count, payload_count = pair_outputs(left, right)
                totals["pairedProfileObservations"] += profile_count
                totals["pairedProfileFieldComparisons"] += profile_count * 102
                totals["pairedFullPayloadByteEqualities"] += payload_count
                if family.startswith("alert-"):
                    require(alert.comparison_value(left["metrics"]) == alert.comparison_value(right["metrics"]), "Corresponding fixture/HIR/profile observations differ")
        reports[family] = {"resultPath": result_path.as_posix(), "resultSha256": sha(result_path), "planSha256": sha(plan_path),
                           "actualProcesses": len(checked), "medians": medians, "comparisons": costs,
                           "timeIncreasesOverFivePercent": [value for value in costs if value["timeIncreaseOverFivePercent"]],
                           "allocationCountOrPeakIncreases": [value for value in costs if value["allocationCountOrPeakIncrease"]],
                           "signedNetLiveDeltaChanges": [value for value in costs if value["signedNetLiveDeltaChanged"]]}
    require(totals == {"processes": 126, "payloads": 3492, "rawStageMeasurements": 4032, "rawMetricValues": 20160,
                      "profileObservations": 5454, "profileFieldObservations": 556308, "pairedProfileObservations": 3342,
                      "pairedProfileFieldComparisons": 340884, "pairedFullPayloadByteEqualities": 2256}, "Complete independent totals differ")
    require(source_binding() == binding, "Frozen source changed during independent audit")
    for report in reports.values():
        exact_file(report["resultPath"], report["resultSha256"])
    return {"status": "passed", "actualExistingProcessesAudited": 126, "newProbeProcesses": 0,
            "producerSuccessBooleansUsedAsProof": False, "sourceBinding": binding, "baseline": baseline_summary,
            "sourceArchive": final_archive, "profileSchema": schema, "phases": phases, "totals": totals, "families": reports,
            "auditScriptSha256": sha(Path(__file__)), "checkerSha256": {name: sha(D / name) for name in ("alert_validation.py", "budget_validation.py")},
            "budgetCallSiteIdentity": {"formula": "Exact fixture direct calls are indicator, K ta.valuewhen calls, plot; zero-based sequential HIR allocation gives plot id K+1.",
                                       "frozenAllocationSourcesSha256": allocation_sources},
            "limits": "Reads original stdout/exit/hash receipts and lossless gzip bytes. Formula replay does not independently reimplement native RuntimeReplica; actual Rust probes and canonical semantic tests qualify that API. Descriptive native requested allocation/time metrics, not RSS or formal statistics."}


def main():
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S.%fZ") + "-" + uuid.uuid4().hex[:8]
    outdir = D / "independent-audit-receipts" / stamp
    outdir.mkdir(parents=True, exist_ok=False)
    initial_script = sha(Path(__file__))
    save(outdir / "started.json", {"auditScriptSha256": initial_script, "startedUtc": datetime.now(timezone.utc).isoformat(), "probesExecuted": 0})
    print("Independent read-only audit:", outdir.as_posix(), flush=True)
    try:
        result = audit(outdir)
        require(sha(Path(__file__)) == initial_script, "Audit code changed during its execution")
        result.update(finishedUtc=datetime.now(timezone.utc).isoformat(), receiptDirectory=outdir.as_posix())
        save(outdir / "result.json", result)
        save(D / "independent-audit-results.json", result)
        save(outdir / "exit.json", {"returncode": 0, "newProbeProcesses": 0})
        print("PASS: 126 existing processes, 3492 original payloads, all raw metrics/profiles/paired bytes verified", flush=True)
    except BaseException as error:
        save(outdir / "failure.json", {"status": "failed", "failure": str(error), "traceback": traceback.format_exc(),
                                       "auditScriptSha256": initial_script, "returncode": 1, "newProbeProcesses": 0})
        print(traceback.format_exc(), file=sys.stderr, flush=True)
        raise


if __name__ == "__main__":
    main()

link_probe.ps1.content:
param(
    [ValidateSet('before','after')] [string] $Tag,
    [ValidateSet('alert','alert_ref','budget')] [string] $Probe
)
$ErrorActionPreference = 'Stop'
Import-Module (Join-Path $PSHOME 'Modules/Microsoft.PowerShell.Utility/Microsoft.PowerShell.Utility.psd1')
Set-Location -LiteralPath 'E:\projects\pine-interpreter'
function Get-ProbeSha256([string] $Path) {
    $stream = [System.IO.File]::OpenRead((Join-Path (Get-Location) $Path))
    $algorithm = [System.Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($algorithm.ComputeHash($stream))).Replace('-', '').ToLowerInvariant() }
    finally { $stream.Dispose(); $algorithm.Dispose() }
}
$probeDirectory = '.local/alert-budget-20261005'
$libraryDirectory = if ($Tag -eq 'before') { "$probeDirectory/baseline" } else { 'target/release' }
$source = if ($Probe -eq 'alert_ref') { "$probeDirectory/alert_ref_probe.rs" } else { "$probeDirectory/${Probe}_probe.rs" }
$sourceHash = Get-ProbeSha256 $source
$additionalSourceHashes = @{}
foreach ($include in @("$probeDirectory/alert_probe_common.rs", "$probeDirectory/budget_probe_common.rs")) {
    if (($Probe.StartsWith('alert') -and $include.EndsWith('alert_probe_common.rs')) -or ($Probe -eq 'budget' -and $include.EndsWith('budget_probe_common.rs'))) {
        if (Test-Path -LiteralPath $include) { $additionalSourceHashes[$include] = Get-ProbeSha256 $include }
    }
}
if ($Probe -eq 'alert_ref' -and $Tag -ne 'after') { throw 'Borrowed probe only supports after' }
$vswhere = Join-Path ${env:ProgramFiles(x86)} 'Microsoft Visual Studio/Installer/vswhere.exe'
$installation = (& $vswhere -latest -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath | Select-Object -First 1)
Import-Module (Join-Path $installation 'Common7/Tools/Microsoft.VisualStudio.DevShell.dll')
Enter-VsDevShell -VsInstallPath $installation -SkipAutomaticLocation -DevCmdArguments '-arch=amd64' | Out-Null
$libraryPaths = @("$libraryDirectory/libpine_runtime.rlib", "$libraryDirectory/libpine_sema.rlib", "$libraryDirectory/libpine_syntax.rlib", "$libraryDirectory/deps/libserde_json-ff9aee5763d82a17.rlib")
$hashes = @{}
foreach ($path in $libraryPaths) { $hashes[$path] = Get-ProbeSha256 $path }
$arguments = @('--edition=2024', '-O', '-C', 'lto=thin', '-C', 'codegen-units=1', '-L', "dependency=$libraryDirectory/deps", '--extern', "pine_runtime=$libraryDirectory/libpine_runtime.rlib", '--extern', "pine_sema=$libraryDirectory/libpine_sema.rlib", '--extern', "pine_syntax=$libraryDirectory/libpine_syntax.rlib", '--extern', "serde_json=$libraryDirectory/deps/libserde_json-ff9aee5763d82a17.rlib")
if ($Probe -eq 'alert_ref') { $arguments += @('--cfg', 'borrowed_delta') }
$ErrorActionPreference = 'Continue'
& rustc $source @arguments -o "$probeDirectory/$Probe-$Tag.exe" *> "$probeDirectory/link-$Probe-$Tag.log"
$linkExit = $LASTEXITCODE
Set-Content "$probeDirectory/link-$Probe-$Tag.exit" $linkExit
if ($linkExit -ne 0) { exit $linkExit }
$ErrorActionPreference = 'Stop'
if ((Get-ProbeSha256 $source) -ne $sourceHash) { throw "Entry source changed while linking: $source" }
foreach ($path in $libraryPaths) { if ((Get-ProbeSha256 $path) -ne $hashes[$path]) { throw "Library changed while linking: $path" } }
foreach ($include in $additionalSourceHashes.Keys) { if ((Get-ProbeSha256 $include) -ne $additionalSourceHashes[$include]) { throw "Included source changed while linking: $include" } }
@{
    tag = $Tag
    probe = $Probe
    libraryHashes = $hashes
    executableSha256 = Get-ProbeSha256 "$probeDirectory/$Probe-$Tag.exe"
    sourceSha256 = $sourceHash
    compilerArguments = $arguments
    additionalSourceHashes = $additionalSourceHashes
    rustc = (& rustc -V)
    sourceManifestSha256 = Get-ProbeSha256 "$probeDirectory/$(if ($Tag -eq 'before') { 'before-' })source-identity.json"
} | ConvertTo-Json -Depth 8 | Set-Content "$probeDirectory/identity-$Probe-$Tag.json" -Encoding utf8
exit 0

performance_runner.py.content:
"""Prepare and orchestrate frozen public probes; never build or link.

Explicit --execute is required for sampling. Each family has a separate unique
receipt directory/results file. Before/after pairs alternate and use fresh
processes. Borrowed is after-only and compared only with completed after-owned.
"""
from __future__ import annotations
import argparse
from datetime import datetime, timezone
import importlib
import os
from pathlib import Path
import re
import statistics
import subprocess

from evidence_common import (D, ROOT, compress_payload, decode_payload, directory,
                             execute, integer, loads, number, read, save, sha)

REPETITIONS,SAMPLES = 3,9
METRICS={"ms","allocatedBytes","allocations","peakAdditionalLiveBytes","liveDeltaBytes"}
PROFILE_SOURCE=ROOT/"crates/pine-runtime/src/output/json/profile.rs"
SPECS={
    "alert-owned":{"probe":"alert","checker":"alert_validation","mode":"owned",
        "singleStages":{"analyze","seedWithoutOutput","confirmed","nextHistorical","nextFormingAfterConfirmation"},
        "repeatedStages":{"formingWithoutOutput","formingApply","returnedChangesClone"},"rawPayloads":34},
    "alert-borrowed":{"probe":"alert_ref","checker":"alert_validation","mode":"borrowed",
        "singleStages":{"analyze","seedWithoutOutput","confirmed","nextHistorical","nextFormingAfterConfirmation"},
        "repeatedStages":{"formingWithoutOutput","formingApply","returnedChangesClone"},"rawPayloads":34},
    "budget":{"probe":"budget","checker":"budget_validation","mode":"owned",
        "singleStages":{"analyze","historicalSeed","realtimeSeedWithoutOutput","confirmedWithoutOutput","nextHistoricalWithoutOutput"},
        "repeatedStages":{"historicalClone","formingWithoutOutput","formingApplyUpdate"},"rawPayloads":12},
}


def resolve(path):
    path=Path(path)
    return path if path.is_absolute() else ROOT/path


def profile_schema():
    fields=re.findall(r'\\"([A-Za-z][A-Za-z0-9]*)\\":',PROFILE_SOURCE.read_text(encoding="utf8"))
    if len(fields)!=102 or len(set(fields))!=102:
        raise ValueError("Expected the exact complete 102-field public profile schema")
    return {"path":PROFILE_SOURCE.as_posix(),"sha256":sha(PROFILE_SOURCE),"fields":sorted(fields)}


def file_identity(path):
    return {"path":path.as_posix(),"sha256":sha(path)}


def prepare(family):
    spec=SPECS[family]
    checker=importlib.import_module(spec["checker"])
    cases=[checker.prepare_case(case) for case in checker.cases()]
    probe=D/(spec["probe"]+"_probe.rs")
    common=D/("alert_probe_common.rs" if family.startswith("alert-") else "budget_probe_common.rs")
    sources=[probe,common,D/"performance_runner.py",D/"evidence_common.py",D/(spec["checker"]+".py")]
    result={"family":family,"cases":cases,"repetitionsPerVersion":REPETITIONS,"samplesPerRepeatedStage":SAMPLES,
            "plannedProcesses":len(cases)*REPETITIONS*(1 if family=="alert-borrowed" else 2),
            "tags":["after"] if family=="alert-borrowed" else ["before","after"],
            "singleStages":sorted(spec["singleStages"]),"repeatedStages":sorted(spec["repeatedStages"]),
            "metricFields":sorted(METRICS),"rawPayloadsPerProcess":spec["rawPayloads"],
            "stageMeasurementsPerProcess":len(spec["singleStages"])+SAMPLES*len(spec["repeatedStages"]),
            "sourceFiles":[file_identity(path) for path in sources],"profileSchema":profile_schema(),
            "probeSource":file_identity(probe),"includeSource":file_identity(common),
            "method":"Repeated-stage process median of nine raw samples, then median of three fresh-process values; single stages use three fresh-process median. All original values and process receipts retained.",
            "comparison":"after-only borrowed against completed after-owned with identical fixture/stage entry revisions; no borrowed before/after pair" if family=="alert-borrowed" else "three fresh-process paired before/after with alternating order",
            "allocationScope":"Allocator request bytes/count and peak additional requested live bytes within each named public call; signed net live delta; not RSS or system transient realloc peaks.",
            "compression":"gzip mtime0 after correctness checks; decoded bytes must exactly match original SHA/bytes before unlinking the validated exact raw filename in this unique receipt directory",
            "probesExecuted":False}
    save(D/(family+"-plan.json"),result)
    return result


def binding():
    manifest=read(D/"source-identity.json")
    changed=[path for path,expected in manifest["files"].items()
             if not (ROOT/path).is_file() or sha(ROOT/path)!=expected]
    if changed:
        raise ValueError("Final frozen production/source set changed: "+repr(changed))
    return {"manifestSha256":sha(D/"source-identity.json"),"archiveSha256":sha(D/"source.tar"),
            "files":len(manifest["files"]),"sourceVerified":True}


def phase(name,source_binding):
    path=D/f"phase-{name}.json"
    value=read(path)
    if (value.get("phase")!=name or value.get("status")!="passed" or value.get("returncode")!=0
            or value.get("before")!=source_binding or value.get("after")!=source_binding
            or value.get("wrapperSha256")!=sha(D/"run_phase.py")
            or value.get("wrapperLogSha256")!=sha(D/f"phase-{name}-wrapper.log")):
        raise ValueError("Required phase is not bound to unchanged passing source: "+name)
    if name.startswith("gate-"):
        paths={"gateLogSha256":D/(name+".log"),"gateExitSha256":D/(name+".exit")}
        exit_path=paths["gateExitSha256"]
    elif name=="release":
        paths={"buildLogSha256":D/"build-release.log","buildExitSha256":D/"build-release.exit"}
        exit_path=paths["buildExitSha256"]
    else:
        _,probe,tag=name.split("-")
        paths={"linkReceiptSha256":D/f"identity-{probe}-{tag}.json","linkLogSha256":D/f"link-{probe}-{tag}.log"}
        exit_path=D/f"link-{probe}-{tag}.exit"
    if int(exit_path.read_text(encoding="utf-8-sig"))!=0 or any(value.get(key)!=sha(item) for key,item in paths.items()):
        raise ValueError("Required phase output/exit identity differs: "+name)
    return {"path":path.as_posix(),"sha256":sha(path),"artifactHashes":{key:sha(item) for key,item in paths.items()}}


def identity(probe,tag,plan):
    path=D/f"identity-{probe}-{tag}.json"
    value=read(path)
    executable=D/f"{probe}-{tag}.exe"
    manifest=D/("before-source-identity.json" if tag=="before" else "source-identity.json")
    link_exit=D/f"link-{probe}-{tag}.exit"
    if (value.get("probe")!=probe or value.get("tag")!=tag
            or sha(executable)!=value.get("executableSha256")
            or sha(resolve(plan["probeSource"]["path"]))!=value.get("sourceSha256")
            or value.get("sourceSha256")!=plan["probeSource"]["sha256"]
            or sha(manifest)!=value.get("sourceManifestSha256")
            or int(link_exit.read_text(encoding="utf-8-sig"))!=0):
        raise ValueError("Exact wrapper/binary/manifest/link identity differs: "+probe+"-"+tag)
    includes=value.get("additionalSourceHashes")
    if not isinstance(includes,dict) or len(includes)!=1:
        raise ValueError("Exactly one shared include must be bound by the link receipt")
    for raw_path,expected in includes.items():
        actual=resolve(raw_path)
        if (actual.resolve()!=resolve(plan["includeSource"]["path"]).resolve()
                or sha(actual)!=expected or expected!=plan["includeSource"]["sha256"]):
            raise ValueError("Exact shared include source identity differs")
    libraries=value.get("libraryHashes")
    if (not isinstance(libraries,dict) or len(libraries)!=4
            or {Path(item).name for item in libraries}!={"libpine_runtime.rlib","libpine_sema.rlib",
                "libpine_syntax.rlib","libserde_json-ff9aee5763d82a17.rlib"}):
        raise ValueError("Expected exact four direct linked libraries")
    archive=read(D/"before-binary-identity.json") if tag=="before" else None
    if archive is not None and archive["beforeManifestSha256"]!=sha(manifest):
        raise ValueError("Before source-to-library proof differs")
    tools=read(D/"before-binary-identity.json")["tools"]
    if value.get("rustc")!=tools["rustc"]["verboseVersion"].splitlines()[0]:
        raise ValueError("Link compiler version differs from sealed baseline")
    for raw_path,expected in libraries.items():
        actual=resolve(raw_path)
        if sha(actual)!=expected:
            raise ValueError("A linked library changed: "+raw_path)
        if archive is not None:
            matching=[row for row in archive["libraries"].values()
                      if resolve(row["archive"]).resolve()==actual.resolve() and row["sha256"]==expected]
            if not actual.resolve().is_relative_to((D/"baseline").resolve()) or len(matching)!=1:
                raise ValueError("Before link uses an unproven/unarchived direct library")
    expected_arguments=['--edition=2024','-O','-C','lto=thin','-C','codegen-units=1','-L','dependency=LIBROOT/deps',
                        '--extern','pine_runtime=LIBROOT/libpine_runtime.rlib','--extern','pine_sema=LIBROOT/libpine_sema.rlib',
                        '--extern','pine_syntax=LIBROOT/libpine_syntax.rlib','--extern','serde_json=LIBROOT/deps/libserde_json-ff9aee5763d82a17.rlib']
    normalized=[argument.replace('.local/alert-budget-20261005/baseline','LIBROOT').replace('target/release','LIBROOT')
                for argument in value["compilerArguments"]]
    if probe=="alert_ref":
        expected_arguments+=['--cfg','borrowed_delta']
    if normalized!=expected_arguments:
        raise ValueError("Frozen optimizing compiler argument set differs")
    return {"binary":executable.as_posix(),"binarySha256":sha(executable),"probeSource":plan["probeSource"],
            "includeSource":plan["includeSource"],"sourceManifestSha256":sha(manifest),
            "linkReceipt":path.as_posix(),"linkReceiptSha256":sha(path),"linkLogSha256":sha(D/f"link-{probe}-{tag}.log"),
            "linkExitSha256":sha(link_exit),"normalizedCompilerArguments":normalized,"link":value}


def quiescence():
    command=("Get-CimInstance Win32_Process | Where-Object { "
             f"$_.ProcessId -ne {os.getpid()} -and ("
             "$_.Name -match '^(cargo|rustc|maturin|link|cl|msbuild|pine.*|alert.*|budget.*|serialization.*|capacity.*|valuewhen.*|heap.*|differential.*)\\.exe$' "
             "-or ($_.Name -match '^(python|pythonw)\\.exe$' -and "
             "$_.CommandLine -match '(performance_runner|serialization_runner|capacity_runner|valuewhen_runner)\\.py')) "
             "} | Select-Object Name,ProcessId | ConvertTo-Json")
    completed=subprocess.run(['powershell.exe','-NoProfile','-Command',command],cwd=ROOT,capture_output=True,timeout=30)
    if completed.returncode!=0 or completed.stdout.decode('utf-8-sig').strip():
        raise ValueError("Windows build/test/measurement quiescence check did not pass")
    return {"matchingWindowsBuildOrMeasurementProcesses":[],
            "limitation":"Name/command matching excludes this runner; coordinator separately keeps WSL/builds/other measurements quiescent. No claim of complete OS inactivity."}


def prerequisites(family,plan):
    spec=SPECS[family]
    source_binding=binding()
    if profile_schema()!=plan["profileSchema"]:
        raise ValueError("Prepared complete public profile schema differs")
    for row in plan["sourceFiles"]+[case["source"] for case in plan["cases"]]:
        if sha(resolve(row["path"]))!=row["sha256"]:
            raise ValueError("Frozen helper/probe/fixture differs: "+row["path"])
    phases={name:phase(name,source_binding) for name in ('gate-windows','gate-linux','release',f'link-{spec["probe"]}-after')}
    identities={tag:identity(spec["probe"],tag,plan) for tag in plan["tags"]}
    if identities["after"]["sourceManifestSha256"]!=source_binding["manifestSha256"]:
        raise ValueError("After binary is linked against a different final source")
    if "before" in identities and identities["before"]["normalizedCompilerArguments"]!=identities["after"]["normalizedCompilerArguments"]:
        raise ValueError("Owned before/after compiler arguments differ")
    baseline=read(D/"before-binary-identity.json")
    if (baseline["beforeArchiveSha256"]!=sha(D/"before-source.tar")
            or baseline["beforeManifestSha256"]!=sha(D/"before-source-identity.json")):
        raise ValueError("Sealed baseline archive/source manifest identity differs")
    for row in baseline["libraries"].values():
        if sha(resolve(row["archive"]))!=row["sha256"]:
            raise ValueError("Sealed baseline compiler artifact changed")
    for row in baseline["tools"].values():
        if sha(resolve(row["executable"]))!=row["executableSha256"]:
            raise ValueError("Sealed tool executable changed")
    return {"sourceBinding":source_binding,"phases":phases,"identities":identities,
            "baselineArchive":{"identitySha256":sha(D/"before-binary-identity.json"),
                "sourceArchiveSha256":sha(D/"before-source.tar"),"compilerArtifacts":len(baseline["libraries"])},
            "quiescence":quiescence()}


def validate_stages(metrics,spec):
    stages=metrics["stages"]
    if not isinstance(stages,dict) or set(stages)!=spec["singleStages"]|spec["repeatedStages"]:
        raise ValueError("Unknown or missing named public-call stage")
    medians={}
    for name,value in stages.items():
        samples=value if name in spec["repeatedStages"] else [value]
        if not isinstance(samples,list) or len(samples)!=(SAMPLES if name in spec["repeatedStages"] else 1):
            raise ValueError("Missing raw stage samples")
        for row in samples:
            if not isinstance(row,dict) or set(row)!=METRICS:
                raise ValueError("Missing original allocator/time metric")
            number(row["ms"])
            for field in METRICS-{"ms"}:
                integer(row[field],None if field=="liveDeltaBytes" else 0)
            if row["peakAdditionalLiveBytes"]<max(0,row["liveDeltaBytes"]):
                raise ValueError("Stage additional peak is below its positive net live increase")
        medians[name]={field:statistics.median(row[field] for row in samples) for field in sorted(METRICS)}
    return medians


def compare_rows(checker,left,right):
    comparison = getattr(checker,"comparison_value",None)
    left_value=comparison(left["metrics"]) if comparison else left["correctness"]
    right_value=comparison(right["metrics"]) if comparison else right["correctness"]
    if left_value!=right_value:
        raise ValueError("Complete public profiles/correctness/HIR metadata differ across corresponding observations")
    if len(left["payloads"])!=len(right["payloads"]):
        raise ValueError("Raw payload count differs")
    for old,new in zip(left["payloads"],right["payloads"]):
        if (old["role"]!=new["role"] or old["originalSha256"]!=new["originalSha256"]
                or old["originalBytes"]!=new["originalBytes"] or decode_payload(old)!=decode_payload(new)):
            raise ValueError("Decoded full public JSON differs at role "+old["role"])


def summarize(rows):
    result=[]
    for case in dict.fromkeys(row["case"]["name"] for row in rows):
        selected=[row for row in rows if row["case"]["name"]==case]
        versions={}
        for tag in dict.fromkeys(row["tag"] for row in selected):
            actual=[row for row in selected if row["tag"]==tag]
            if len(actual)!=REPETITIONS:
                raise ValueError("Incomplete fresh-process version group")
            versions[tag]={stage:{field:statistics.median(row["processMedians"][stage][field] for row in actual)
                                 for field in sorted(METRICS)} for stage in actual[0]["processMedians"]}
        result.append({"case":case,"versionMedians":versions})
    return result


def compare_medians(left,right,left_name,right_name):
    rows=[]
    for old,new in zip(left,right):
        if old["case"]!=new["case"]:
            raise ValueError("Median cases differ")
        a,b=old["versionMedians"][left_name],new["versionMedians"][right_name]
        for stage in a:
            for metric in sorted(METRICS):
                before,after=a[stage][metric],b[stage][metric]
                rows.append({"case":old["case"],"stage":stage,"metric":metric,"left":before,"right":after,
                    "delta":after-before,"ratio":after/before if before!=0 else None,
                    "percentChange":(after-before)/abs(before)*100 if before!=0 else None,
                    "timeIncreaseOverFivePercent":metric=="ms" and before>0 and after>before*1.05,
                    "allocationCountOrPeakIncrease":metric in {"allocatedBytes","allocations","peakAdditionalLiveBytes"} and after>before,
                    "signedNetLiveDeltaChanged":metric=="liveDeltaBytes" and after!=before})
    return rows


def run(family,timeout):
    spec=SPECS[family]
    plan_path=D/(family+"-plan.json")
    plan=read(plan_path)
    if plan.get("family")!=family or plan.get("probesExecuted") is not False:
        raise ValueError("Expected frozen preparation-only plan")
    checker=importlib.import_module(spec["checker"])
    pre=prerequisites(family,plan)
    owned=None
    if family=="alert-borrowed":
        owned=read(D/"alert-owned-results.json")
        if (owned.get("status")!="passed" or owned.get("qualifiedProcesses")!=60
                or owned["prerequisites"]["sourceBinding"]!=pre["sourceBinding"]
                or owned["plan"]["includeSource"]!=plan["includeSource"]):
            raise ValueError("Borrowed needs completed owned60 against this same source/common")
    out=directory(family)
    rows=[]
    result={"family":family,"status":"running","qualifiedProcesses":0,"attemptedProcesses":0,
            "startedUtc":datetime.now(timezone.utc).isoformat(),"plan":plan,"planSha256":sha(plan_path),
            "prerequisites":pre,"receiptDirectory":out.as_posix(),"processes":rows,
            "qualificationScope":"This unique complete fresh batch only; no previous failed attempts or observations are mixed."}
    destination=D/(family+"-results.json")
    if destination.exists():
        raise ValueError("A result file already exists; explicitly preserve/exclude it before a new fresh batch")
    save(out/"plan.json",plan)
    for row in plan["sourceFiles"]:
        copied=out/Path(row["path"]).name
        copied.write_bytes(resolve(row["path"]).read_bytes())
        if sha(copied)!=row["sha256"]:
            raise ValueError("Archived runner/probe/include/helper identity differs")
    lock=D/"measurement.lock"
    with lock.open("x",encoding="utf8") as handle:
        handle.write(str(os.getpid())+" "+family+" "+out.as_posix()+"\n")
    try:
        for case in plan["cases"]:
            for repetition in range(REPETITIONS):
                tags=["after"] if family=="alert-borrowed" else (["before","after"] if repetition%2==0 else ["after","before"])
                pair=[]
                for tag in tags:
                    if prerequisites(family,plan)!=pre:
                        raise ValueError("Source/phases/identities changed before a process")
                    stem=f'{case["name"]}-{tag}-{repetition}'
                    receipt=out/(stem+".metrics.json")
                    arguments=[str(case["count"]),str(case["prefixChars"] if family.startswith("alert-") else case["bars"]),receipt.as_posix()]
                    result["attemptedProcesses"]+=1
                    process,raw=execute(out,stem,[pre["identities"][tag]["binary"],*arguments],timeout)
                    row={"case":case,"tag":tag,"repetition":repetition,"process":process,
                         "inputSourceSha256":case["source"]["sha256"],"binaryIdentity":pre["identities"][tag],
                         "phaseSourceBinding":pre["sourceBinding"],"individuallyValidated":False}
                    rows.append(row)
                    save(out/"batch.json",result)
                    if process["returncode"]!=0:
                        raise ValueError("Probe process did not exit zero: "+stem)
                    lines=raw.splitlines()
                    if len(lines)!=1 or not lines[0] or receipt.read_bytes()!=lines[0]:
                        raise ValueError("Expected exactly one stdout JSON line matching on-disk receipt")
                    metrics=loads(lines[0])
                    medians=validate_stages(metrics,spec)
                    check=(checker.validate(metrics,case,plan["profileSchema"]["fields"],mode=spec["mode"])
                           if family.startswith("alert-") else checker.validate(metrics,case,plan["profileSchema"]["fields"]))
                    if family.startswith("alert-"):
                        payloads=checker.validate_payloads(metrics,case,out,receipt=receipt)
                    else:
                        checked=checker.validate_payloads(metrics,case,out)
                        payloads=[]
                        for role,item in checked.items():
                            if resolve(item["path"]).resolve()!=receipt.with_suffix(f".{role}.json").resolve():
                                raise ValueError("Budget payload does not match exact process receipt role")
                            payloads.append({"role":role,"path":resolve(item["path"]).resolve().as_posix(),
                                "originalSha256":item["sha256"],"originalBytes":item["bytes"],
                                "independentValidation":item["pythonOracle"]})
                    if len(payloads)!=spec["rawPayloads"]:
                        raise ValueError("Incorrect complete payload count")
                    row.update(metrics=metrics,processMedians=medians,correctness=check,payloads=[],
                               uncompressedPayloadIdentity=payloads,
                               metricReceipt={"path":receipt.as_posix(),"sha256":sha(receipt)})
                    for payload in payloads:
                        row["payloads"].append(compress_payload(payload,out))
                    row["individuallyValidated"]=True
                    if prerequisites(family,plan)!=pre:
                        raise ValueError("Source/phases/identities changed after a process")
                    pair.append(row)
                    save(out/"batch.json",result)
                    print(stem,"validated",len(rows),"of",plan["plannedProcesses"],flush=True)
                if len(pair)==2:
                    compare_rows(checker,pair[0],pair[1])
                else:
                    matching=[item for item in owned["processes"] if item["case"]["name"]==case["name"]
                              and item["tag"]=="after" and item["repetition"]==repetition]
                    if len(matching)!=1:
                        raise ValueError("Missing corresponding owned-after entry")
                    compare_rows(checker,matching[0],pair[0])
        medians=summarize(rows)
        costs=compare_medians(owned["medians"],medians,"after","after") if owned else compare_medians(medians,medians,"before","after")
        result.update(status="passed",qualifiedProcesses=len(rows),medians=medians,comparisons=costs,
            timeIncreasesOverFivePercent=[item for item in costs if item["timeIncreaseOverFivePercent"]],
            allocationCountOrPeakIncreases=[item for item in costs if item["allocationCountOrPeakIncrease"]],
            signedNetLiveDeltaChanges=[item for item in costs if item["signedNetLiveDeltaChanged"]],
            finalPrerequisites=prerequisites(family,plan),finishedUtc=datetime.now(timezone.utc).isoformat(),
            comparisonLabels={"left":"after-owned" if owned else "before-owned","right":"after-borrowed" if owned else "after-owned"})
        if result["attemptedProcesses"]!=plan["plannedProcesses"] or result["finalPrerequisites"]!=pre:
            raise ValueError("Batch count or final identity differs")
        save(out/"batch.json",result)
        save(destination,result)
    except BaseException as error:
        result.update(status="failed_excluded",qualifiedProcesses=0,failure=str(error),
                      individuallyValidatedProcesses=sum(row["individuallyValidated"] for row in rows),
                      finishedUtc=datetime.now(timezone.utc).isoformat())
        save(out/"batch.json",result)
        save(out/"excluded-identity.json",{"status":"excluded_entire_incomplete_batch","qualifiedProcesses":0,
             "attemptedProcesses":result["attemptedProcesses"],"individuallyValidatedProcesses":result["individuallyValidatedProcesses"],
             "planSha256":sha(out/"plan.json"),"sourceFiles":plan["sourceFiles"],"prerequisites":pre,"failure":str(error)})
        raise
    finally:
        if lock.read_text(encoding="utf8").startswith(str(os.getpid())+" "+family+" "+out.as_posix()):
            lock.unlink()


def main():
    parser=argparse.ArgumentParser()
    parser.add_argument("family",choices=SPECS)
    parser.add_argument("--execute",action="store_true")
    parser.add_argument("--timeout",type=float,default=600)
    arguments=parser.parse_args()
    if arguments.timeout<=0:
        parser.error("timeout must be positive")
    if arguments.execute:
        run(arguments.family,arguments.timeout)
    else:
        plan=prepare(arguments.family)
        print(arguments.family,"prepared",plan["plannedProcesses"],"processes; no probe/build/link executed",flush=True)


if __name__=="__main__":
    main()

