def build(attempt):
    manifest, binding = frozen_binding()
    before = read(D / "before-source-identity.json")
    baseline = read(D / "before-binary-identity.json")
    require(len(baseline["libraries"]) == 311 and baseline["beforeManifestSha256"] == sha(D / "before-source-identity.json") and
            baseline["beforeArchiveSha256"] == sha(D / "before-source.tar"), "sealed baseline archive binding differs")
    datasets = {family: read(D / (family + "-results.json")) for family in FAMILIES}
    schemas = [dataset_check(datasets[family], family, binding) for family in FAMILIES]
    require(schemas[0] == schemas[1] == schemas[2], "public complete profile schema differs between families")
    phases = {name: verify_phase(name, binding) for name in FINAL_PHASES}
    gates = canonical_gates(phases, binding)
    audit, audit_execution = verify_audit(datasets, binding)
    pair_counts = validate_pairs(datasets)
    totals = {"qualifiedProcesses": sum(len(value["processes"]) for value in datasets.values()),
              "stageMeasurements": sum(32 * len(value["processes"]) for value in datasets.values()),
              "metricValues": sum(160 * len(value["processes"]) for value in datasets.values()),
              "rawPayloads": sum(len(row["payloads"]) for value in datasets.values() for row in value["processes"])}
    require(totals == EXPECTED_TOTALS, "computed final aggregate totals differ")
    registry = ProfileRegistry(schemas[0])
    normalized = {family: registry.normalize(dataset) for family, dataset in datasets.items()}
    for family in FAMILIES:
        require(registry.expand(normalized[family]) == datasets[family], "normalization lost original dataset structure")
        for compact, original in zip(normalized[family]["processes"], datasets[family]["processes"]):
            require(registry.expand(compact["metrics"]) == original["metrics"], "normalization lost original process metrics")
    normalized_audit = registry.normalize(audit)
    require(registry.expand(normalized_audit) == audit, "normalization lost audit structure")
    normalization = {"kind": "lossless_report_profile_dictionary_interning", "marker": PROFILE_REF,
        "canonicalEncoding": "UTF-8 JSON, ensure_ascii=false, sort_keys=true, separators=(',',':'), allow_nan=false",
        "uniqueProfiles": len(registry.values), "profileReferences": registry.references,
        "allOriginalProcessMetricsExpandedEqual": True, "allOriginalFamilyDatasetsExpandedEqual": True,
        "allIndependentAuditExpandedEqual": True, "meaning": "report storage normalization only; no measurement or qualification is omitted"}
    exclusions = archive_exclusions()
    costs = summary_costs(datasets)
    markdown = render(datasets, audit, gates, costs, exclusions, normalization, binding, before)
    changed = {name: {"beforeSha256": before["files"].get(name), "afterSha256": manifest["files"].get(name)}
               for name in sorted(set(before["files"]) | set(manifest["files"])) if before["files"].get(name) != manifest["files"].get(name)}
    result = {"status": "qualified_in_scoped_native_measurements", "reportDate": REPORT_DATE,
        "generatedUtc": datetime.now(timezone.utc).isoformat(), "generator": artifact(__file__),
        "report": {"path": "docs/" + MD_NAME, "sha256": sha_bytes(markdown.encode("utf-8"))},
        "source": {"sourceBinding": binding, "baselineSourceFiles": len(before["files"]),
            "changedFileIdentities": changed, "manifests": {name: artifact(D / name) for name in ("before-source-identity.json", "source-identity.json")},
            "reportScope": "these two report files were generated after frozen-source gates and are not part of their source snapshot"},
        "baselineCompiledArchive": baseline, "phases": phases, "canonicalGates": gates,
        "datasetIdentities": {family: artifact(D / (family + "-results.json")) for family in FAMILIES},
        "qualificationAccounting": {**totals, "familyQualifiedProcesses": COUNTS, "pairedDecodedPayloads": pair_counts,
            "versionStageMetricComparisons": 1040, "borrowedIsAfterOnly": True},
        "profileStorageNormalization": normalization, "profileRegistry": registry.values,
        "datasets": normalized, "independentAudit": normalized_audit,
        "independentAuditIdentity": artifact(D / AUDIT_FILENAME), "independentAuditActualExit": audit_execution,
        "helpers": helpers(), "allMeasuredCosts": costs, "exclusions": exclusions,
        "rawArtifacts": {name: artifact(D / name) for name in ("before-source.tar", "source.tar", "gate-windows.log", "gate-linux.log", "build-release.log")},
        "remainingDebt": [
            {"topic": "all_retained_state_byte_budget", "status": "not_implemented_or_resource_qualified", "scope": "valuewhen events only in this repair"},
            {"topic": "math_array_secondary_dispatch", "status": "remaining_source_debt_not_benchmarked_here"},
            {"topic": "wma_hma_variance_linear_work", "status": "remaining_trigger_specific_O(L)_paths_not_benchmarked_here"},
            {"topic": "full_resource_RSS_matrix", "status": "not_qualified", "scope": "allocator layout requests are not OS RSS"}],
        "limits": [
            "native exact fixture/API measurements only; borrowed compares after-owned to after-ref, never a nonexistent baseline ref API",
            "logical budget covers event count, not arbitrary payload bytes, physical shared leaves, rollback copies, request output caches, all collections or RSS",
            "System request cumulative bytes/count, phase-relative live peak and signed net live are distinct metrics; none proves allocator residency/RSS/leaks",
            "return disposal, encoders, oracles and report work are outside each stage timer/counter; internal runtime replacement is inside",
            "requested backup clones may compact Small/rolling physical histories; semantic rollback is not complete physical-profile equality",
            "three fresh process medians and sample ranges are descriptive; no significance, noise-causality or interpreter-wide speedup claim",
            "source archives, libraries, executables, public JSON and gzip raw files remain local ignored evidence; tracked records retain hashes and locators"],
    }
    encoded = (json.dumps(result, ensure_ascii=False, indent=2, allow_nan=False) + "\n").encode("utf-8")
    # Parse the exact future tracked bytes and expand again, ensuring serialized
    # registry/ref storage is also lossless, not merely an in-memory assertion.
    serialized = loads(encoded)
    saved_registry = serialized["profileRegistry"]
    require(saved_registry == registry.values, "serialized profile registry differs")
    for family in FAMILIES:
        require(registry.expand(serialized["datasets"][family]) == datasets[family], "serialized dataset normalization is lossy")
        for compact, original in zip(serialized["datasets"][family]["processes"], datasets[family]["processes"]):
            require(registry.expand(compact["metrics"]) == original["metrics"], "serialized process raw metrics are lossy")
    require(registry.expand(serialized["independentAudit"]) == audit, "serialized audit normalization is lossy")
    frozen_binding()  # Final pre-write source check. Never rebuild on failure.
    for family in FAMILIES:
        require(sha(D / (family + "-results.json")) == result["datasetIdentities"][family]["sha256"], "dataset changed before report write")
    require(sha(D / AUDIT_FILENAME) == result["independentAuditIdentity"]["sha256"], "audit changed before report write")
    md_stage, json_stage = attempt / MD_NAME, attempt / JSON_NAME
    md_stage.write_bytes(markdown.encode("utf-8"))
    json_stage.write_bytes(encoded)
    docs = ROOT / "docs"
    md_path, json_path = docs / MD_NAME, docs / JSON_NAME
    require(md_path.parent.resolve() == docs.resolve() and json_path.parent.resolve() == docs.resolve(), "report output escaped docs")
    md_stage.replace(md_path)
    json_stage.replace(json_path)
    require(sha(md_path) == result["report"]["sha256"], "written markdown SHA differs")
    return {"status": "written", "markdown": artifact(md_path), "json": artifact(json_path),
            **totals, "profileStorageNormalization": normalization,
            "timeIncreasesOverFivePercent": len(costs["timeIncreasesOverFivePercent"]),
            "allocationOrPeakIncreases": len(costs["allAllocationOrPeakIncreases"]),
            "signedNetLiveIncreases": len(costs["allSignedLiveDeltaIncreases"])}


def main():
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S.%fZ") + "-" + uuid.uuid4().hex[:8]
    attempt = D / "report-attempts" / stamp
    attempt.mkdir(parents=True, exist_ok=False)
    (attempt / "build_report.py").write_bytes(Path(__file__).read_bytes())
    try:
        receipt = build(attempt)
    except BaseException as error:
        receipt = {"status": "failed", "error": str(error), "generatorSha256": sha(__file__),
                   "traceback": traceback.format_exc(), "finishedUtc": datetime.now(timezone.utc).isoformat()}
        (attempt / "receipt.json").write_text(json.dumps(receipt, ensure_ascii=False, indent=2) + "\n", encoding="utf-8", newline="\n")
        raise
    (attempt / "receipt.json").write_text(json.dumps(receipt, ensure_ascii=False, indent=2) + "\n", encoding="utf-8", newline="\n")
    print(json.dumps(receipt, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

