"""Write durable reports only from complete, audited, source-bound receipts.

Standard library only. Never import producers/auditors, spawn a process, build,
link, execute a probe or rerun a gate. Preparation of this file writes nothing
tracked. Running it requires all three final families and an independently
recorded actual audit exit. Profile interning is report storage normalization,
and expansion is checked against the original data before either report writes.
"""
from __future__ import annotations

from datetime import datetime, timezone
import gzip
import hashlib
import json
import math
from pathlib import Path
import re
import statistics
import traceback
import uuid

D = Path(__file__).resolve().parent
ROOT = D.parents[1]
REPORT_DATE = "2026-10-05"
MD_NAME = "ALERT_VALUEWHEN_BUDGET_REPAIR_20261005.md"
JSON_NAME = "ALERT_VALUEWHEN_BUDGET_REPAIR_RESULTS_20261005.json"
FAMILIES = ("alert-owned", "alert-borrowed", "budget")
COUNTS = {"alert-owned": 60, "alert-borrowed": 30, "budget": 36}
PAYLOAD_COUNTS = {"alert-owned": 34, "alert-borrowed": 34, "budget": 12}
SINGLES = {
    "alert-owned": {"analyze", "seedWithoutOutput", "confirmed", "nextHistorical", "nextFormingAfterConfirmation"},
    "alert-borrowed": {"analyze", "seedWithoutOutput", "confirmed", "nextHistorical", "nextFormingAfterConfirmation"},
    "budget": {"analyze", "historicalSeed", "realtimeSeedWithoutOutput", "confirmedWithoutOutput", "nextHistoricalWithoutOutput"},
}
REPEATED = {
    "alert-owned": {"formingWithoutOutput", "formingApply", "returnedChangesClone"},
    "alert-borrowed": {"formingWithoutOutput", "formingApply", "returnedChangesClone"},
    "budget": {"historicalClone", "formingWithoutOutput", "formingApplyUpdate"},
}
METRICS = {"ms", "allocatedBytes", "allocations", "peakAdditionalLiveBytes", "liveDeltaBytes"}
EXPECTED_TOTALS = {"qualifiedProcesses": 126, "stageMeasurements": 4032,
                   "metricValues": 20160, "rawPayloads": 3492}
EXPECTED_AUDIT_TOTALS = {"processes": 126, "payloads": 3492,
    "rawStageMeasurements": 4032, "rawMetricValues": 20160,
    "profileObservations": 5454, "profileFieldObservations": 556308,
    "pairedProfileObservations": 3342, "pairedProfileFieldComparisons": 340884,
    "pairedFullPayloadByteEqualities": 2256}
AUDIT_PHASES = ("gate-windows", "gate-linux", "release", "link-alert-after",
                "link-alert_ref-after", "link-budget-after")
FINAL_PHASES = (*AUDIT_PHASES, "link-alert-before", "link-budget-before")
AUDIT_FILENAME = "independent-audit-results.json"
PROFILE_REF = "$profileSha256"


def require(condition, message):
    if not condition:
        raise ValueError(message)


def resolve(path):
    value = Path(path)
    return value if value.is_absolute() else ROOT / value


def sha_bytes(raw):
    return hashlib.sha256(raw).hexdigest()


def sha(path):
    return sha_bytes(Path(path).read_bytes())


def canonical(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False).encode("utf-8")


def pairs(values):
    result = {}
    for key, value in values:
        require(key not in result, "duplicate JSON key: " + key)
        result[key] = value
    return result


def number(token):
    value = float(token)
    require(math.isfinite(value), "nonfinite JSON float")
    return value


def constant(token):
    raise ValueError("nonfinite JSON constant: " + token)


def loads(raw):
    return json.loads(raw, object_pairs_hook=pairs, parse_float=number, parse_constant=constant)


def read(path):
    return loads(Path(path).read_text(encoding="utf-8-sig"))


def integer(value, minimum=None):
    require(type(value) is int and (minimum is None or value >= minimum), "invalid integer measurement")
    return value


def numeric(value):
    require(type(value) in (int, float) and math.isfinite(value), "invalid numeric measurement")
    return value


def artifact(path, content=False):
    path = resolve(path).resolve()
    require(path.is_file(), "missing artifact: " + str(path))
    locator = path.relative_to(ROOT).as_posix() if path.is_relative_to(ROOT) else path.as_posix()
    result = {"path": locator, "sha256": sha(path), "bytes": path.stat().st_size}
    if content:
        result["content"] = path.read_text(encoding="utf-8-sig")
    return result


def verify_identity(row):
    require(isinstance(row, dict) and isinstance(row.get("path"), str), "artifact identity needs a path")
    actual = resolve(row["path"])
    require(actual.is_file() and sha(actual) == row.get("sha256"), "artifact identity changed: " + str(actual))
    if "bytes" in row:
        require(actual.stat().st_size == row["bytes"], "artifact size changed: " + str(actual))


def frozen_binding():
    path = D / "source-identity.json"
    manifest = read(path)
    require(isinstance(manifest.get("files"), dict), "source manifest is missing files")
    for name, expected in manifest["files"].items():
        current = ROOT / name
        require(current.is_file() and sha(current) == expected, "frozen production source differs: " + name)
    return manifest, {"manifestSha256": sha(path), "archiveSha256": sha(D / "source.tar"),
                      "files": len(manifest["files"]), "sourceVerified": True}


def verify_phase(name, binding):
    receipt = read(D / ("phase-" + name + ".json"))
    require(receipt.get("phase") == name and receipt.get("status") == "passed" and receipt.get("returncode") == 0,
            "required final phase did not pass: " + name)
    require(receipt.get("before") == binding and receipt.get("after") == binding,
            "final phase source binding differs: " + name)
    require(receipt.get("wrapperSha256") == sha(D / "run_phase.py") and
            receipt.get("wrapperLogSha256") == sha(D / ("phase-" + name + "-wrapper.log")),
            "final phase wrapper identity differs: " + name)
    if name.startswith("gate-"):
        log, exit_path = D / (name + ".log"), D / (name + ".exit")
        expected = {"gateLogSha256": sha(log), "gateExitSha256": sha(exit_path)}
    elif name == "release":
        log, exit_path = D / "build-release.log", D / "build-release.exit"
        expected = {"buildLogSha256": sha(log), "buildExitSha256": sha(exit_path)}
    else:
        _, probe, tag = name.split("-")
        log, exit_path = D / f"link-{probe}-{tag}.log", D / f"link-{probe}-{tag}.exit"
        expected = {"linkLogSha256": sha(log), "linkReceiptSha256": sha(D / f"identity-{probe}-{tag}.json")}
    require(int(exit_path.read_text(encoding="utf-8-sig")) == 0,
            "required actual phase exit is nonzero: " + name)
    require(all(receipt.get(key) == value for key, value in expected.items()), "final phase output hash differs: " + name)
    return {**artifact(D / ("phase-" + name + ".json")), "receipt": receipt,
            "log": artifact(log), "actualExitFile": artifact(exit_path)}


def canonical_gates(phases, binding):
    """Derive suite totals from final hash-bound logs, not audit assumptions."""
    result = {}
    for host in ("windows", "linux"):
        phase = phases["gate-" + host]
        path = resolve(phase["log"]["path"])
        # Normalize only presentation controls and line endings. The original
        # log bytes and SHA remain preserved as the evidence artifact.
        text = re.sub(r"\x1b\[[0-?]*[ -/]*[@-~]", "", path.read_text(encoding="utf-8-sig"))
        lines = text.splitlines()
        rust = []
        for index, line in enumerate(lines, 1):
            match = re.match(r"^test result: (ok|FAILED)\. (\d+) passed; (\d+) failed; (\d+) ignored; (\d+) measured; (\d+) filtered out;", line)
            if match:
                status, passed, failed, ignored, measured, filtered = match.groups()
                require(status == "ok" and int(failed) == 0, "canonical Rust failure: " + host)
                rust.append({"line": index, "passed": int(passed), "failed": int(failed),
                             "ignored": int(ignored), "measured": int(measured), "filtered": int(filtered)})
        require(rust and sum(row["passed"] for row in rust) == 7385, "canonical Rust passed total differs: " + host)
        tooling = [(index, re.fullmatch(r"Ran (\d+) tests in [\d.]+s", line))
                   for index, line in enumerate(lines, 1) if line.startswith("Ran ")]
        require(len(tooling) == 1 and tooling[0][1] is not None and int(tooling[0][1].group(1)) == 166,
                "canonical tooling Ran total differs: " + host)
        tooling_ok = [(index, re.fullmatch(r"OK(?: \(skipped=(\d+)\))?", line))
                      for index, line in enumerate(lines, 1) if line.startswith("OK")]
        require(len(tooling_ok) == 1 and tooling_ok[0][1] is not None, "canonical tooling success differs: " + host)
        skipped = int(tooling_ok[0][1].group(1) or 0)
        require(skipped == (1 if host == "linux" else 0), "canonical tooling skip total differs: " + host)
        python = [(index, re.fullmatch(r"=+\s+(\d+) passed in [\d.]+s\s+=+", line))
                  for index, line in enumerate(lines, 1) if re.match(r"=+\s+\d+ passed in ", line)]
        require(len(python) == 1 and python[0][1] is not None and int(python[0][1].group(1)) == 794,
                "canonical wheel Python passed total differs: " + host)
        structure = [(index, line) for index, line in enumerate(lines, 1)
                     if line == "Structural guardrail passed: checked 403 production Rust source files."]
        node = [(index, line) for index, line in enumerate(lines, 1)
                if line == "wasm Node smoke passed: instantiate, analyze, run, compile/run, combined hosts, JS exceptions"]
        parity = [(index, line) for index, line in enumerate(lines, 1) if line.startswith("Host parity guard passed:")]
        require(len(structure) == len(node) == len(parity) == 1, "canonical structural/Node/parity proof differs: " + host)
        require("Built wheel for abi3 Python" in text and "venv" in text and "Successfully installed pine-compat-runtime-0.3.0rc1" in text,
                "canonical fresh wheel/venv installation evidence missing: " + host)
        result[host] = {"rustPassed": 7385, "rustResultBlocks": rust,
            "pythonPassed": 794, "toolingRan": 166, "toolingSkipped": skipped,
            "toolingPassed": 166 - skipped, "productionRustFiles": 403,
            "nodeWasmSmokePassed": True, "hostParityPassed": True,
            "freshWheelVenv": True, "actualExitCode": 0, "sourceBinding": binding,
            "log": phase["log"], "phase": {key: phase[key] for key in ("path", "sha256", "bytes")},
            "actualExitFile": phase["actualExitFile"],
            "evidenceLines": {"toolingRan": tooling[0][0], "toolingOK": tooling_ok[0][0],
                "python": python[0][0], "structure": structure[0][0], "node": node[0][0], "hostParity": parity[0][0]},
            "derivation": "Parsed original final canonical logs after phase/log/exit/source hash verification; these totals are not supplied by the independent audit schema."}
    return result


def profile_fields(dataset):
    schema = dataset["plan"]["profileSchema"]
    verify_identity(schema)
    names = schema["fields"]
    require(type(names) is list and len(names) == 102 and len(set(names)) == 102,
            "public profile schema must have exactly 102 unique fields")
    return frozenset(names)


def check_metric(sample):
    require(type(sample) is dict and set(sample) == METRICS, "missing or unexpected raw metric")
    require(numeric(sample["ms"]) >= 0, "negative internal Instant timing")
    for key in METRICS - {"ms"}:
        integer(sample[key], None if key == "liveDeltaBytes" else 0)
    require(sample["peakAdditionalLiveBytes"] >= max(0, sample["liveDeltaBytes"]),
            "stage peak below positive net live delta")


def process_medians(row, family):
    stages = row["metrics"]["stages"]
    require(set(stages) == SINGLES[family] | REPEATED[family], "raw named stage schema differs")
    result = {}
    for name, value in stages.items():
        samples = value if name in REPEATED[family] else [value]
        require(type(samples) is list and len(samples) == (9 if name in REPEATED[family] else 1),
                "raw stage sample count differs")
        for sample in samples:
            check_metric(sample)
        result[name] = {field: statistics.median(sample[field] for sample in samples) for field in sorted(METRICS)}
    require(result == row["processMedians"], "stored process medians differ from all raw samples")
    return result


def decoded_payload(row):
    path = resolve(row["path"])
    compressed = path.read_bytes()
    require(len(compressed) == row["gzipBytes"] and sha_bytes(compressed) == row["gzipSha256"],
            "compressed raw payload identity changed")
    raw = gzip.decompress(compressed)
    require(len(raw) == row["originalBytes"] and sha_bytes(raw) == row["originalSha256"],
            "decoded raw public JSON identity changed")
    require(row.get("compression") == "gzip" and row.get("mtime") == 0 and
            row.get("originalRemovedAfterVerifiedRoundtrip") is True, "payload compression provenance differs")
    loads(raw)
    return raw


def dataset_check(dataset, family, binding):
    require(dataset.get("family") == family and dataset.get("status") == "passed", "family not complete: " + family)
    require(dataset.get("qualifiedProcesses") == COUNTS[family] and len(dataset["processes"]) == COUNTS[family],
            "qualified family process count differs: " + family)
    require(dataset["attemptedProcesses"] == COUNTS[family], "incomplete attempt mixed into final family")
    require(dataset["prerequisites"]["sourceBinding"] == binding and
            dataset["finalPrerequisites"] == dataset["prerequisites"], "family prerequisite/source binding differs")
    plan = dataset["plan"]
    require(plan["family"] == family and plan["plannedProcesses"] == COUNTS[family] and
            plan["probesExecuted"] is False and plan["samplesPerRepeatedStage"] == 9 and
            plan["stageMeasurementsPerProcess"] == 32, "family preparation contract differs")
    require(sha(D / (family + "-plan.json")) == dataset["planSha256"] and
            read(D / (family + "-plan.json")) == plan, "frozen family plan changed")
    for identity in plan["sourceFiles"] + [item["source"] for item in plan["cases"]]:
        verify_identity(identity)
    fields = profile_fields(dataset)
    rows = dataset["processes"]
    wanted = {(case["name"], tag, repetition) for case in plan["cases"] for tag in plan["tags"] for repetition in range(3)}
    actual = {(row["case"]["name"], row["tag"], row["repetition"]) for row in rows}
    require(actual == wanted and len(actual) == len(rows), "duplicate or missing fresh case/tag/repetition")
    for row in rows:
        require(row["individuallyValidated"] is True and row["process"]["returncode"] == 0,
                "raw child process not actually successful")
        require(row["phaseSourceBinding"] == binding, "process final source differs")
        verify_identity(row["metricReceipt"])
        require(read(resolve(row["metricReceipt"]["path"])) == row["metrics"], "raw metric receipt content differs")
        process_medians(row, family)
        process = row["process"]
        for name in ("stdout", "stderr", "exit"):
            require(sha(resolve(process[name])) == process[name + "Sha256"], "raw process output/exit identity differs")
        exit_receipt = read(resolve(process["exit"]))
        require(exit_receipt["returncode"] == 0 and exit_receipt["command"] == process["command"],
                "raw process actual exit/command differs")
        require(len(row["payloads"]) == PAYLOAD_COUNTS[family], "incomplete raw payload set")
        require(len({payload["role"] for payload in row["payloads"]}) == PAYLOAD_COUNTS[family], "duplicate raw payload role")
        for payload in row["payloads"]:
            decoded_payload(payload)
    return fields


def alert_profiles(metrics):
    result = {name: metrics[name] for name in ("seedProfile", "confirmedProfile", "historicalProfile",
                                              "finalPreviewProfile", "finalConfirmedProfile")}
    for index, check in enumerate(metrics["formingChecks"]):
        result[f"forming[{index}].preview"] = check["previewProfile"]
        result[f"forming[{index}].confirmed"] = check["confirmedProfile"]
    require(len(result) == 41, "alert complete profile count differs")
    return result


def budget_profiles(metrics):
    result = {name: metrics[name] for name in ("seedProfile", "realtimeSeedProfile", "confirmedProfile", "finalProfile")}
    for index, check in enumerate(metrics["cloneChecks"]):
        result[f"clone[{index}]"] = check["profile"]
    for index, check in enumerate(metrics["formingChecks"]):
        result[f"forming[{index}].preview"] = check["profile"]
        result[f"forming[{index}].confirmed"] = check["confirmedProfile"]
    require(len(result) == 49, "budget complete profile count differs")
    return result


def paired_rows(left, right, left_tag, right_tag):
    lookup = {(row["case"]["name"], row["repetition"]): row for row in right["processes"] if row["tag"] == right_tag}
    result = []
    for row in left["processes"]:
        if row["tag"] == left_tag:
            key = row["case"]["name"], row["repetition"]
            require(key in lookup, "corresponding fresh paired process is missing")
            result.append((row, lookup[key]))
    require(len(result) == len(lookup), "paired process cardinality differs")
    return result


def validate_pairs(datasets):
    result = {}
    for family, left_family, left_tag, right_tag in (
        ("alert-owned", "alert-owned", "before", "after"),
        ("alert-borrowed", "alert-owned", "after", "after"),
        ("budget", "budget", "before", "after"),
    ):
        count = 0
        for old, new in paired_rows(datasets[left_family], datasets[family], left_tag, right_tag):
            reader = budget_profiles if family == "budget" else alert_profiles
            require(reader(old["metrics"]) == reader(new["metrics"]), "complete corresponding profiles differ: " + family)
            for before, after in zip(old["payloads"], new["payloads"]):
                require(before["role"] == after["role"] and decoded_payload(before) == decoded_payload(after),
                        "decoded full public JSON differs: " + family)
                count += 1
        result[family] = count
    require(result == {"alert-owned": 1020, "alert-borrowed": 1020, "budget": 216}, "paired payload count differs")
    return result


class ProfileRegistry:
    def __init__(self, fields):
        self.fields = fields
        self.values = {}
        self.references = 0

    def normalize(self, value):
        if type(value) is dict:
            require(PROFILE_REF not in value, "reserved normalization marker already present in original data")
            if frozenset(value) == self.fields:
                identity = sha_bytes(canonical(value))
                prior = self.values.setdefault(identity, value)
                require(canonical(prior) == canonical(value), "profile canonical SHA collision")
                self.references += 1
                return {PROFILE_REF: identity}
            return {key: self.normalize(item) for key, item in value.items()}
        if type(value) is list:
            return [self.normalize(item) for item in value]
        return value

    def expand(self, value):
        if type(value) is dict:
            if set(value) == {PROFILE_REF}:
                require(value[PROFILE_REF] in self.values, "profile reference missing from registry")
                profile = self.values[value[PROFILE_REF]]
                require(sha_bytes(canonical(profile)) == value[PROFILE_REF], "profile registry identity differs")
                return profile
            return {key: self.expand(item) for key, item in value.items()}
        if type(value) is list:
            return [self.expand(item) for item in value]
        return value


def summary_costs(datasets):
    all_comparisons = []
    for family, left_family, left_tag, right_tag in (
        ("alert-owned", "alert-owned", "before", "after"),
        ("alert-borrowed", "alert-owned", "after", "after"),
        ("budget", "budget", "before", "after"),
    ):
        for case in datasets[family]["plan"]["cases"]:
            name = case["name"]
            left = sorted((row for row in datasets[left_family]["processes"] if row["case"]["name"] == name and row["tag"] == left_tag), key=lambda row: row["repetition"])
            right = sorted((row for row in datasets[family]["processes"] if row["case"]["name"] == name and row["tag"] == right_tag), key=lambda row: row["repetition"])
            require(len(left) == len(right) == 3, "three fresh process groups are required")
            for stage in sorted(SINGLES[family] | REPEATED[family]):
                for metric in sorted(METRICS):
                    before = [row["processMedians"][stage][metric] for row in left]
                    after = [row["processMedians"][stage][metric] for row in right]
                    bm, am = statistics.median(before), statistics.median(after)
                    all_comparisons.append({"family": family, "case": name, "stage": stage, "metric": metric,
                        "comparison": "after-owned → after-borrowed" if family == "alert-borrowed" else "before-owned → after-owned",
                        "beforeSamples": before, "afterSamples": after, "beforeMedian": bm, "afterMedian": am,
                        "beforeMin": min(before), "beforeMax": max(before), "afterMin": min(after), "afterMax": max(after),
                        "delta": am - bm, "ratio": am / bm if bm > 0 else None,
                        "percentChange": (am / bm - 1) * 100 if bm > 0 else None,
                        "unit": "ms" if metric == "ms" else "count" if metric == "allocations" else "bytes"})
    require(len(all_comparisons) == 1040, "expected 26 cases × 8 stages × 5 comparison metrics")
    return {"allStageMetricComparisons": all_comparisons,
            "timeIncreasesOverFivePercent": [row for row in all_comparisons if row["metric"] == "ms" and row["beforeMedian"] > 0 and row["afterMedian"] > row["beforeMedian"] * 1.05],
            "timeZeroBaselinePositive": [row for row in all_comparisons if row["metric"] == "ms" and row["beforeMedian"] == 0 and row["afterMedian"] > 0],
            "allAllocationOrPeakIncreases": [row for row in all_comparisons if row["metric"] in {"allocatedBytes", "allocations", "peakAdditionalLiveBytes"} and row["afterMedian"] > row["beforeMedian"]],
            "allChangedSignedLiveDeltas": [row for row in all_comparisons if row["metric"] == "liveDeltaBytes" and row["afterMedian"] != row["beforeMedian"]],
            "allSignedLiveDeltaIncreases": [row for row in all_comparisons if row["metric"] == "liveDeltaBytes" and row["afterMedian"] > row["beforeMedian"]],
            "interpretation": "Descriptive median of three fresh process medians; 9 samples per repeated stage. Signed net-live changes are not RSS, leak or absolute operation-peak evidence."}


def archive_exclusions():
    result = {"gateAttempts": {}, "targetedArtifacts": {}, "performanceExcludedBatches": [], "auditAttempts": {}}
    for directory in sorted(D.glob("gate-attempt*")):
        require(directory.is_dir() and (directory / "archive.json").is_file(), "gate-attempt archive receipt missing")
        receipt = read(directory / "archive.json")
        require(receipt.get("status") in {"failedExcluded", "failedGateAttemptExcluded"}, "gate-attempt not explicitly excluded")
        require(receipt.get("windowsExit") != 0 and receipt.get("linuxExit") != 0 and
                receipt.get("performanceProbesExecuted") == 0, "failed gate archive claims passing/performance qualification")
        for name, identity in receipt["files"].items():
            require(sha(directory / name) == identity["sha256"], "archived failed-gate artifact differs")
        result["gateAttempts"][directory.name] = {"archive": artifact(directory / "archive.json"), "receipt": receipt}
    require({"gate-attempt1", "gate-attempt2"} <= set(result["gateAttempts"]), "original failed gate attempts were not preserved")
    targeted = (
        "alert-targeted-inflight-source-failure.json", "alert-targeted-inflight-source-failure.log",
        "retained-budget-targeted-transcript.json", "scratch-before.log", "scratch-before-realtime.rs", "scratch-repro-test.rs",
        "request-physical-profile-assertion-failure.log", "request-profile-failed-test.rs",
        "request-profile-invalid-clone-compile-failure.log",
    )
    for name in targeted:
        result["targetedArtifacts"][name] = artifact(D / name, content=name.endswith(".json"))
    for path in sorted(D.glob("*-receipts/*/excluded-identity.json")):
        receipt = read(path)
        require(receipt.get("qualifiedProcesses") == 0, "excluded incomplete batch claims qualification")
        result["performanceExcludedBatches"].append({**artifact(path), "receipt": receipt})
    for directory in sorted((D / "independent-audit-receipts").glob("*")):
        if directory.is_dir():
            result["auditAttempts"][directory.name] = {
                path.name: {**artifact(path), "receipt": read(path)} for path in sorted(directory.glob("*.json"))}
    result["interpretations"] = [
        "gate-attempt1 is a real source-bound failed gate: E_VALUEWHEN_BUDGET was missing from the diagnostic reference; no performance qualification was obtained.",
        "gate-attempt2 is a real failed gate: the new WASM test called the revision getter as a function, and both actual exits were 1. Its successful release/before links bind a superseded smoke-test snapshot and are excluded from final prerequisites.",
        "retained-budget-targeted-transcript.json contains reconstructed actual tool-response excerpts and outcomes, not original redirected stdout/stderr or frozen-source canonical qualification.",
        "alert-targeted in-flight compile output was preserved from combined tool output; it lacks a historical frozen source snapshot.",
        "scratch-before.log reproduces loss of selection capacity 16→8 before repair; the final passing test is qualified by final source-bound gates.",
        "Requested rollback's cloned Small/rolling histories may legally compact physical capacity (observed 8→6) while preserving values. The final requested test does not assert complete physical-profile equality.",
        "The test's accidental RealtimeRuntime.clone() use was a preserved compilation failure, then corrected; it is not a successful test or runtime failure.",
    ]
    return result


def helpers():
    paths = sorted({*D.glob("*.py"), *D.glob("*.ps1"), *D.glob("*.sh"), *D.glob("*probe*.rs")})
    return {path.name: artifact(path, content=True) for path in paths}


def verify_audit(datasets, binding):
    path = D / AUDIT_FILENAME
    audit = read(path)
    require(audit.get("status") == "passed", "independent audit is not passed")
    require(audit.get("totals") == EXPECTED_AUDIT_TOTALS, "independent audit complete totals differ")
    require(audit.get("actualExistingProcessesAudited") == 126 and audit.get("newProbeProcesses") == 0 and
            audit.get("producerSuccessBooleansUsedAsProof") is False, "independent audit execution boundary differs")
    require(audit.get("sourceBinding") == binding, "independent audit source binding differs")
    audited = audit.get("families")
    require(type(audited) is dict and set(audited) == set(FAMILIES), "independent audit must bind all three datasets")
    for family in FAMILIES:
        identity = audited[family]
        require(resolve(identity["resultPath"]).resolve() == (D / (family + "-results.json")).resolve() and
                identity.get("resultSha256") == sha(D / (family + "-results.json")) and
                identity.get("planSha256") == sha(D / (family + "-plan.json")) and
                identity.get("actualProcesses") == COUNTS[family], "audit family binding differs: " + family)
        for key in ("medians", "comparisons", "timeIncreasesOverFivePercent", "allocationCountOrPeakIncreases", "signedNetLiveDeltaChanges"):
            require(identity[key] == datasets[family][key], "independent audit family raw-derived summary differs: " + family + "/" + key)
    auditor = D / "independent_audit.py"
    auditor_sha = sha(auditor)
    require(audit.get("auditScriptSha256") == auditor_sha, "independent auditor source changed")
    require(audit.get("checkerSha256") == {name: sha(D / name) for name in ("alert_validation.py", "budget_validation.py")},
            "independent audit reused checker source changed")
    require(audit.get("profileSchema") == datasets["alert-owned"]["plan"]["profileSchema"],
            "independent audit complete profile schema differs")
    baseline = audit.get("baseline")
    require(type(baseline) is dict and baseline.get("identitySha256") == sha(D / "before-binary-identity.json") and
            baseline.get("sourceArchiveSha256") == sha(D / "before-source.tar") and baseline.get("compilerArtifacts") == 311 and
            baseline.get("sourceFiles") == len(read(D / "before-source-identity.json")["files"]) and
            baseline.get("baseCommit") == read(D / "before-source-identity.json")["base_commit"],
            "independent audit sealed baseline differs")
    archive = audit.get("sourceArchive")
    require(type(archive) is dict and resolve(archive["path"]).resolve() == (D / "source.tar").resolve() and
            archive.get("sha256") == binding["archiveSha256"] and archive.get("files") == binding["files"],
            "independent audit final source archive differs")
    require(type(audit.get("phases")) is dict and set(audit["phases"]) == set(AUDIT_PHASES),
            "independent audit final prerequisite phase set differs")
    for name in AUDIT_PHASES:
        phase = audit["phases"][name]
        phase_path = D / ("phase-" + name + ".json")
        require(resolve(phase["path"]).resolve() == phase_path.resolve() and phase.get("sha256") == sha(phase_path),
                "independent audit phase binding differs: " + name)
        receipt = read(phase_path)
        require(phase.get("artifactHashes") == {key: receipt[key] for key in receipt
                    if key in {"gateLogSha256", "gateExitSha256", "buildLogSha256", "buildExitSha256", "linkReceiptSha256", "linkLogSha256"}},
                "independent audit phase artifact hashes differ: " + name)
    directory = resolve(audit["receiptDirectory"]).resolve()
    require(directory.parent == (D / "independent-audit-receipts").resolve() and read(directory / "result.json") == audit,
            "independent audit durable result receipt differs")
    require(read(directory / "exit.json") == {"returncode": 0, "newProbeProcesses": 0} and
            read(directory / "started.json").get("auditScriptSha256") == auditor_sha,
            "independent audit internal start/exit receipt differs")
    execution_path = D / "audit-execution.json"
    execution = read(execution_path)
    require(type(execution.get("actualExitCode")) is int and execution["actualExitCode"] == 0 and
            execution.get("auditResultsSha256") == sha(path) and execution.get("auditScriptSha256") == auditor_sha and
            execution.get("auditorSha256") == auditor_sha and bool(execution.get("toolEvidence")),
            "independent audit actual exit0 evidence/binding is missing")
    return audit, {**artifact(execution_path), "receipt": execution}


def fmt(value):
    return f"{value:,}" if type(value) is int else f"{value:.7g}"


def transition(row):
    return fmt(row["beforeMedian"]) + " → " + fmt(row["afterMedian"])


def growth(row):
    return f"{row['percentChange']:+.2f}%" if row["percentChange"] is not None else f"基线≤0，净差 {fmt(row['delta'])}"


def ranges(row):
    return f"{fmt(row['beforeMin'])}–{fmt(row['beforeMax'])} → {fmt(row['afterMin'])}–{fmt(row['afterMax'])}"


def table(headers, rows):
    material = list(rows)
    return "\n".join(["| " + " | ".join(headers) + " |", "|" + "|".join("---" for _ in headers) + "|",
                      *("| " + " | ".join(str(item).replace("|", "\\|") for item in row) + " |" for row in material)]) if material else "本批无满足条件的项目。"


def metric_row(costs, family, case, stage, metric):
    rows = [row for row in costs["allStageMetricComparisons"] if (row["family"], row["case"], row["stage"], row["metric"]) == (family, case, stage, metric)]
    require(len(rows) == 1, "unique rendered stage comparison missing")
    return rows[0]


